/* GENERATED by tools/build.js from content/skills/<track>/ and content/datasets/tracks.json. Do not edit by hand: change the source and run "node tools/build.js". */
/* TRACKS = Skill Mode tracks (same shape as LEVELS). TRACK_DATA = downloadable files the track topics use. */
const TRACKS=[
{"id":"sql","kind":"track","order":1,"cls":"sql","name":"SQL for BI","tag":"Track","tagline":"The SQL behind every model: grain, joins, window functions, loading facts and making slow source queries fast.","seo":"SQL for Power BI developers: practice joins, grain, CTEs, window functions, deduplication, views, incremental extraction and query tuning on a realistic company dataset, with answers checked automatically.","intro":"Not database administration: the SQL a BI developer writes and reads every week. Everything runs on the Northwind company pack. Use SQL Server Developer or Express (closest to most jobs), DuckDB (no install: it reads the CSVs directly) or SQLite. The model answers are written in portable SQL and executed in our CI against SQLite, so their numbers are guaranteed to match the expected results.","setup":"Load the seven CSVs from data/experience/company/ as tables named orders, order_lines, returns, customers, products, regions and fx_rates. DuckDB: CREATE TABLE orders AS SELECT * FROM 'orders.csv'; and so on. SQL Server: Import Flat File wizard in SSMS.","stage":"engineer","topics":[{"id":"sql-query","name":"Querying for BI: grain, joins and aggregation","ds":["NWOrders","NWOrderLines","NWCustomers","NWRegions","NWFx"],"skills":["sql","modeling"],"stage":"analyst","why":{"matters":"Most wrong numbers in BI are join mistakes: a join that multiplies rows, or one that silently drops them. SQL is where you see the grain clearly.","failure":"An analyst joins orders to order lines and counts rows as orders; the dashboard reports twice as many orders as the business has.","use":"Whenever data comes from a database: check the grain of every table and of every result before aggregating.","avoid":"Writing the whole model in one giant query. Keep views at a clear grain and let the semantic model do the slicing."},"verified":{"date":"2026-10-01","context":"Portable SQL tested on SQLite 3.47 in CI; SQL Server and DuckDB syntax notes","review_after_days":365},"refs":[{"title":"SELECT (Transact-SQL)","url":"https://learn.microsoft.com/en-us/sql/t-sql/queries/select-transact-sql"},{"title":"Joins (SQL Server)","url":"https://learn.microsoft.com/en-us/sql/relational-databases/performance/joins"}],"asg":[{"t":"Q1 2026 sales by region","time":"40 min","ds":"orders, order_lines, regions, fx_rates","guidance":"A","steps":["Load the company pack into your SQL engine (see Before you start).","order_lines contains exact duplicate rows from a re-export. In a CTE, keep one copy of each (SELECT DISTINCT * is enough here).","Join the lines to orders. Keep only Status = 'Completed', OrderDate from 2026-01-01 to 2026-03-31, and exclude the test customer C19999.","Line value = ROUND(Qty × UnitPrice × (100 − DiscountPct) / 100, 2). Convert EUR lines to USD: join fx_rates on the order month (first 7 characters of OrderDate) and Currency, and multiply; round each line to cents.","Join regions on SalesRegionKey and group by RegionName. Add a grand total in a second query, or with ROLLUP if your engine has it."],"exp":"Five rows. West $60,740, South $58,572, East $48,802, Central $64,587, Europe $22,050; total $254,751."},{"t":"Count orders, lines and customers correctly","time":"30 min","ds":"orders, order_lines","guidance":"B","brief":"Sales wants one row per channel for Q1 2026 with the number of orders, order lines and buying customers, plus a total row. The totals must be right, not just the channel rows.","req":["Same filters as the previous assignment (deduplicated, completed, no test customer, Q1 2026).","Show in a comment why COUNT(*) after the join is the wrong way to count orders.","Explain why the channel rows don't add up to the total for customers."],"exp":"Total: 583 orders, 1,187 lines, 280 customers. The customers column doesn't add up across channels, because some customers buy through more than one."},{"t":"The customer list that lost customers","time":"30 min","ds":"customers, orders, order_lines","guidance":"C","brief":"Marketing asked for every customer with their Q1 2026 sales, including customers who bought nothing (they want to win them back). The query they were given returns only 280 rows, but the company has 420 real customers. Find out why and fix it.","req":["Return one row per customer (excluding the test account) with Q1 2026 gross sales, 0 when they bought nothing.","Explain the bug in one sentence."],"exp":"420 rows, of which 140 have 0. The cause: a LEFT JOIN followed by a WHERE condition on the right-hand table turns it back into an inner join."}],"int":[{"q":"What does \"grain\" mean, and why check it before writing a join?","a":"Grain is what one row represents: one order, one order line, one customer per day. Joining tables at different grains repeats the coarser rows (one order × its lines), so any sum or count of the coarser table's values is multiplied. Check the key of each table and of the result before aggregating."},{"q":"Difference between WHERE and ON in a LEFT JOIN?","a":"Conditions in ON decide which right-hand rows match; unmatched left rows are kept with NULLs. Conditions in WHERE filter after the join, so a WHERE on a right-hand column removes the NULL rows and silently makes it an inner join. Put right-hand filters in the ON clause when you want to keep all left rows."},{"q":"COUNT(*) vs COUNT(column) vs COUNT(DISTINCT column)?","a":"COUNT(*) counts rows, COUNT(column) counts non-null values, COUNT(DISTINCT column) counts different non-null values. After joining orders to lines, COUNT(*) counts lines; orders need COUNT(DISTINCT OrderID)."},{"q":"Why do distinct counts not add up across categories?","a":"The same entity can appear in several categories (a customer buying online and in store). Each category counts it once, the total counts it once overall, so the category rows add up to more than the total. It's correct, and it's why distinct counts are non-additive measures."}],"ass":[{"type":"mcq","q":"SELECT COUNT(*) FROM orders o JOIN order_lines l ON l.OrderID = o.OrderID returns:","o":["The number of orders","The number of order lines that have a matching order","The number of customers","The number of orders with more than one line"],"a":1,"why":"The result has one row per matching line, so COUNT(*) counts lines."},{"type":"mcq","q":"A LEFT JOIN from customers to orders with WHERE orders.OrderDate >= '2026-01-01' returns:","o":["All customers","Only customers with at least one order on or after that date","Only customers without orders","An error"],"a":1,"why":"The WHERE condition removes the rows where OrderDate is NULL, i.e. customers without orders. Move it into the ON clause to keep them."},{"type":"task","q":"Write a query that returns the grain (the key columns and whether they are unique) of each table in the company pack.","hint":"For each table compare COUNT(*) with COUNT(DISTINCT key) (or with a GROUP BY on the candidate key HAVING COUNT(*) > 1). order_lines will surprise you."}],"module":"sql"},{"id":"sql-window","name":"CTEs, window functions and deduplication","ds":["NWOrderLines","NWOrders","NWCustomers","NWProducts"],"skills":["sql","testing"],"stage":"developer","why":{"matters":"Window functions answer the questions BI is asked every day (top N, running totals, previous period, latest row per key) without self-joins, and ROW_NUMBER is the standard tool for removing duplicates safely.","failure":"A load deduplicates with SELECT DISTINCT on a table that has a changing timestamp column: nothing is removed, and the fact doubles.","use":"Ranking, running totals, period-over-period, keeping the latest version of a row, gaps and islands.","avoid":"Using window functions to do what the semantic model will do anyway at query time (running totals over the visual's axis are often better as DAX or visual calculations)."},"verified":{"date":"2026-10-01","context":"Portable SQL tested on SQLite 3.47 in CI","review_after_days":365},"refs":[{"title":"OVER clause (Transact-SQL)","url":"https://learn.microsoft.com/en-us/sql/t-sql/queries/select-over-clause-transact-sql"},{"title":"ROW_NUMBER (Transact-SQL)","url":"https://learn.microsoft.com/en-us/sql/t-sql/functions/row-number-transact-sql"}],"asg":[{"t":"Remove the duplicated lines with ROW_NUMBER","time":"25 min","ds":"order_lines","guidance":"B","brief":"The March re-export duplicated some order lines. SELECT DISTINCT works today, but next time the duplicates may differ in a load timestamp. Write a deduplication that keeps exactly one row per (OrderID, LineNo) whatever the other columns contain.","req":["One row per (OrderID, LineNo).","Say how many rows you removed, and how you would choose which copy to keep if the copies differed."],"exp":"7,252 rows in, 7,215 rows out: 37 duplicates removed."},{"t":"Top products and a running total","time":"30 min","ds":"order_lines, orders, products","guidance":"B","brief":"For the Q1 2026 review, Jordan wants the top three products by gross sales and the cumulative gross sales month by month.","req":["Use RANK or ROW_NUMBER for the top three (no TOP or LIMIT, so it works everywhere).","Running total by month with SUM() OVER (ORDER BY …).","Same filters and currency rules as the previous topic."],"exp":"Top three: Riverstone Kayak 10 $53,397, Drift Paddle Board $32,749, Summit 65L Backpack $21,945. Running total: January $107,539, February $178,287, March $254,751."},{"t":"How dependent are we on one customer?","time":"30 min","ds":"order_lines, orders, customers","guidance":"C","brief":"The CFO asks how concentrated Q1 2026 sales are. Answer with numbers, and say whether the business should worry.","req":["Share of Q1 gross sales from the largest customer, and from the top 10.","A one-sentence answer for the CFO."],"exp":"The largest customer, Summit Outfitters Co., is 15.4% of Q1 2026 gross sales ($39,351). Combined with Sprint 01 (they stopped ordering in February) that is a material risk."}],"int":[{"q":"ROW_NUMBER, RANK and DENSE_RANK: what's the difference?","a":"All number rows within a partition in a given order. ROW_NUMBER gives unique numbers even for ties; RANK gives ties the same number and skips the next ones (1, 1, 3); DENSE_RANK gives ties the same number without gaps (1, 1, 2). For deduplication use ROW_NUMBER; for \"top 3 including ties\" use RANK or DENSE_RANK."},{"q":"How do you keep the latest version of each customer row?","a":"ROW_NUMBER() OVER (PARTITION BY CustomerID ORDER BY UpdatedAt DESC) AS rn, then keep rn = 1. Make the ORDER BY deterministic (add a tie-breaker) or the chosen row can change between runs."},{"q":"When is a CTE better than a subquery?","a":"For readability and reuse within one statement: each step gets a name, and you can test the steps one at a time. Performance is usually the same; a CTE is not a temporary table unless your engine materialises it."},{"q":"What does the window frame in SUM() OVER (ORDER BY Month) default to, and why does it matter?","a":"With ORDER BY and no frame, most engines use RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, which treats ties in the ORDER BY as the same position. For running totals over unique keys that's fine; with duplicates in the ordering column, specify ROWS BETWEEN … explicitly."}],"ass":[{"type":"mcq","q":"Which removes duplicates even when the duplicate rows differ in a LoadedAt column?","o":["SELECT DISTINCT *","ROW_NUMBER() OVER (PARTITION BY OrderID, LineNo ORDER BY LoadedAt DESC) = 1","GROUP BY *","UNION"],"a":1,"why":"DISTINCT compares all columns, so rows that differ in LoadedAt survive. Partitioning by the business key keeps exactly one per key."},{"type":"mcq","q":"Two products tie for second place. Which function returns 1, 2, 2, 4?","o":["ROW_NUMBER","RANK","DENSE_RANK","NTILE"],"a":1,"why":"RANK gives ties the same rank and skips the next number."},{"type":"task","q":"Write a query that shows, for each month of 2026, gross sales and the change versus the previous month, using LAG.","hint":"Aggregate to one row per month in a CTE first, then LAG(Gross) OVER (ORDER BY Month)."}],"module":"sql"},{"id":"sql-load","name":"Views, incremental extraction and idempotent loads","ds":["NWOrders","NWOrderLines","NWFx"],"skills":["sql","warehousing","deployment"],"stage":"engineer","why":{"matters":"Power BI should read from stable, documented views at a clear grain, and loads should be safe to re-run. That is what makes refresh failures recoverable.","failure":"A nightly load is re-run after a failure and appends the same day twice; March revenue doubles in the board pack.","use":"A view per fact and dimension that the model reads; watermark-based incremental extraction with a lookback; delete-and-insert or MERGE on the business key.","avoid":"Business logic spread across Power Query steps in five models; it belongs in one view (or the warehouse) so every consumer agrees."},"verified":{"date":"2026-10-01","context":"Portable SQL tested on SQLite 3.47 in CI; MERGE syntax note for SQL Server","review_after_days":365},"refs":[{"title":"CREATE VIEW (Transact-SQL)","url":"https://learn.microsoft.com/en-us/sql/t-sql/statements/create-view-transact-sql"},{"title":"MERGE (Transact-SQL)","url":"https://learn.microsoft.com/en-us/sql/t-sql/statements/merge-transact-sql"},{"title":"Incremental refresh and real-time data in Power BI","url":"https://learn.microsoft.com/en-us/power-bi/connect-data/incremental-refresh-overview"}],"asg":[{"t":"A view Power BI can trust","time":"40 min","ds":"orders, order_lines, fx_rates","guidance":"B","brief":"Replace the Power Query steps from Sprint 01 with one view, vw_FactSales, that every model can read.","req":["One row per order line, deduplicated; completed orders only; test customer excluded.","Only the columns a model needs, with clear names and types; amounts in USD.","Include OrderDate and PostingDate so both Sales and Finance definitions are possible."],"exp":"For Q1 2026 the view returns 1,187 rows totalling $254,751 gross USD, the same as the Sprint 01 model."},{"t":"Incremental extraction with a watermark","time":"30 min","ds":"orders","guidance":"B","brief":"The last successful load ran with a watermark of 2026-03-24. Extract only what changed since then, but remember that orders can still change status (cancellations) and get returns after they are first loaded.","req":["Rows after the watermark.","The same with a 7-day lookback, and why the lookback exists.","Where the watermark should be stored and when it should move."],"exp":"51 orders after the watermark; 105 with a 7-day lookback (from 2026-03-17). The full table has 3,715."},{"t":"The load that doubled March","time":"40 min","ds":"order_lines","guidance":"C","brief":"Last night's fact load failed half-way and was re-run. It uses INSERT INTO fact_sales SELECT … for the load date. The March total in the warehouse is now far too high. Make the load safe to run any number of times.","req":["Show the failure mode with a small test (run the load twice).","Write an idempotent version (delete-and-insert for the batch, or insert-where-not-exists on the key, or MERGE).","Prove that running it twice leaves the same row count."],"exp":"After two runs of the idempotent load the table has 7,215 rows, exactly as after one."}],"int":[{"q":"Why point Power BI at views instead of tables?","a":"A view is a contract: stable names, the right grain, business rules applied once, and only needed columns. The underlying tables can change without breaking every model, and query folding still works because a view is just a query."},{"q":"What is a watermark and why use a lookback?","a":"The highest change date (or ID) already loaded; the next load takes rows after it. A lookback re-reads the last few days because rows can still change after first load (late returns, status changes, late-arriving rows) and clocks or transactions can be out of order."},{"q":"What makes a load idempotent?","a":"Running it twice gives the same result as running it once. Typical patterns: delete the batch's partition then insert it; insert only keys that don't exist; or MERGE on the business key with update and insert branches."},{"q":"How does Power BI incremental refresh relate to this?","a":"Incremental refresh partitions the table by date using RangeStart/RangeEnd parameters, refreshes only recent partitions and can detect changes. It relies on query folding to push those filters to the source, so the view must be foldable and the date filter must be on a column the source can index."}],"ass":[{"type":"mcq","q":"A nightly load runs INSERT INTO fact SELECT … WHERE LoadDate = @d. It fails half-way and is re-run. What happens?","o":["Nothing; databases prevent duplicates","The rows inserted before the failure are inserted again","The re-run updates the existing rows","The table is truncated first"],"a":1,"why":"A plain INSERT has no idea what's already there. Delete the batch first or insert only missing keys."},{"q":"Which column is the best watermark for extracting changed orders?","type":"mcq","o":["OrderDate","A LastModified timestamp maintained by the source system","OrderID","The load date of the BI table"],"a":1,"why":"Orders change after they are placed (cancellations, returns). Only a modification timestamp catches those; OrderDate misses them."},{"type":"task","q":"Write the view for dim_customer with one row per customer, including a row for \"Unknown\" (key -1) that facts can point to when the customer is missing.","hint":"SELECT … FROM customers UNION ALL SELECT '-1', 'Unknown', … ; see the warehousing track for why the unknown member matters."}],"module":"sql"},{"id":"sql-tune","name":"Making slow source queries fast","ds":["SlowQuery","NWOrders","NWOrderLines","NWReturns"],"skills":["sql","performance"],"stage":"senior","why":{"matters":"Refresh time is usually source-query time. A 22-minute query makes every refresh slow, blocks incremental refresh and loads the source system everyone else uses.","failure":"A function on a date column (YEAR(OrderDate) = 2026) forces a full scan of 72 million rows every night, and nobody notices until the refresh window overlaps the working day.","use":"Read the execution plan, make predicates sargable, remove implicit conversions, select only needed columns, replace row-by-row subqueries with joins or EXISTS, and index for the access path.","avoid":"Adding indexes blindly: every index slows writes and costs storage. Fix the query first, then index for the remaining access pattern."},"verified":{"date":"2026-10-01","context":"SQL Server execution plan and index design guidance (Microsoft Learn); rewrites tested on SQLite in CI","review_after_days":365},"refs":[{"title":"Execution plan overview","url":"https://learn.microsoft.com/en-us/sql/relational-databases/performance/execution-plans"},{"title":"Index architecture and design guide","url":"https://learn.microsoft.com/en-us/sql/relational-databases/sql-server-index-design-guide"},{"title":"Query folding in Power Query","url":"https://learn.microsoft.com/en-us/power-query/query-folding-basics"}],"asg":[{"t":"The 22-minute query","time":"60 min","ds":"slow_query.sql","guidance":"C","brief":"The source query feeding FactSales now takes 22 minutes and the refresh window is at risk. Kenji sent the query and the plan summary (slow_query.sql). Investigate the query and its access pattern.","req":["List every problem in the query and the plan, and what each one costs.","Write a corrected query that returns the same rows.","Suggest the index (or indexes) you would ask Kenji for, and why.","Describe the expected downstream impact on the Power BI refresh and on incremental refresh."],"exp":"Run on the company pack, the original logic and your rewrite return the same 1,171 rows (raw lines of completed 2026 orders with no return). The rewrite uses a date range, matching join types, NOT EXISTS and only the needed columns."},{"t":"Sargable or not?","time":"20 min","ds":"—","guidance":"B","brief":"An index exists on Orders(OrderDate) and another on Customers(Email). For each predicate decide whether SQL Server can seek on the index, and rewrite those that can't.","req":["WHERE YEAR(OrderDate) = 2026","WHERE OrderDate >= '2026-01-01' AND OrderDate < '2027-01-01'","WHERE CONVERT(date, OrderDate) = '2026-03-31' (OrderDate is datetime2)","WHERE LOWER(Email) = 'ava.patel@example.com'","WHERE Email LIKE 'ava.%'","WHERE Email LIKE '%@example.com'"],"exp":"Seekable: the date range and LIKE 'ava.%'. CONVERT(date, …) on a datetime2 column is a special case SQL Server can still seek on. Not seekable: YEAR(), LOWER() and a leading wildcard; rewrite the first two as ranges or with a computed column, and don't index the third."},{"t":"SQL or Power Query?","time":"30 min","ds":"—","guidance":"D","brief":"Elena asks where these transformations should live for the certified sales model: in the warehouse view, in Power Query, or in DAX. Decide and justify each, considering query folding, reuse and who maintains it.","req":["Deduplicating order lines.","Converting EUR to USD at the monthly rate.","Splitting a full name into first and last name for a slicer.","Excluding the test customer.","A \"days since last order\" column per customer.","Formatting numbers as $1.2M on a card."],"deliverables":["A table: transformation, where, why, risk."],"exp":"Warehouse view: deduplication, currency conversion and test-customer exclusion (shared rules, foldable, one place to fix). Power Query or the view: the name split if the source can't. DAX measure: days since last order (depends on filter context). Model formatting: the $1.2M display. At most two of the six belong in DAX."}],"int":[{"q":"What does \"sargable\" mean?","a":"Search-ARGument-able: a predicate the engine can answer with an index seek. Wrapping the indexed column in a function (YEAR(col), LOWER(col)) or converting it implicitly usually prevents a seek; comparing the bare column with a range or constant allows it."},{"q":"Why is an implicit conversion on a join column expensive?","a":"If one side is int and the other varchar, SQL Server converts one side for every row before comparing, which prevents index seeks and can produce bad cardinality estimates. Fix the data types so both sides match."},{"q":"Correlated subquery vs NOT EXISTS vs LEFT JOIN … IS NULL?","a":"A correlated COUNT(*) subquery evaluated per row can execute millions of times. NOT EXISTS expresses an anti-join that the optimiser can run once as a set operation and stop at the first match. LEFT JOIN … IS NULL is equivalent but can duplicate rows if the right side isn't unique."},{"q":"How does a slow source query affect Power BI beyond refresh time?","a":"It loads the source system, can time out the refresh, makes incremental refresh slower or impossible if filters don't fold, and lengthens recovery after a failure because each retry takes as long."}],"ass":[{"type":"mcq","q":"Which predicate lets SQL Server seek on an index on Orders(OrderDate)?","o":["YEAR(OrderDate) = 2026","OrderDate >= '2026-01-01' AND OrderDate < '2027-01-01'","DATEPART(month, OrderDate) = 3","CAST(OrderDate AS varchar(10)) LIKE '2026%'"],"a":1,"why":"Only the bare column compared with a range is sargable."},{"type":"mcq","q":"A plan shows a Table Scan on Returns executed 41 million times. The likely cause:","o":["Too few CPUs","A correlated subquery evaluated once per outer row","Statistics are up to date","The Returns table is small"],"a":1,"why":"A per-row subquery is executed for every outer row. Rewrite as NOT EXISTS or a join so it runs as one set operation."},{"type":"task","q":"In SQL Server, capture the actual execution plan of your rewritten query and compare logical reads (SET STATISTICS IO ON) with the original.","hint":"Look for scans turning into seeks on Orders(OrderDate), the disappearance of the per-row Returns scan, and fewer pages read."}],"module":"sql"}]},
{"id":"warehousing","kind":"track","order":2,"cls":"dw","name":"Data warehousing patterns","tag":"Track","tagline":"Surrogate keys, slowly changing dimensions, fact table types, role-playing and junk dimensions, calendars, time zones and currencies.","seo":"Data warehousing patterns for Power BI developers: SCD type 2, unknown members, early-arriving facts, accumulating and periodic snapshots, role-playing and junk dimensions, 4-4-5 calendars, time zones and multi-currency, with checked answers.","intro":"The patterns behind every good star schema, practised on Northwind data with SQL and Power BI. These are the ideas that make the difference between a model that answers today's question and one that still answers next year's: history that doesn't rewrite itself, facts at the right grain, and dates, time zones and currencies handled on purpose.","setup":"Use the company pack plus the files in data/tracks/warehousing (customer_changes, early_orders, order_events, web_sessions_local). Any SQL engine works; the model answers are portable SQL tested in CI.","stage":"engineer","topics":[{"id":"dw-keys","name":"Keys and slowly changing dimensions","ds":["CustomerChanges","EarlyOrders","NWCustomers"],"skills":["warehousing","sql","modeling"],"stage":"engineer","why":{"matters":"Customers change segment, tier and region. Without history, last year's sales are silently re-attributed to this year's segment, and reports can't be reproduced.","failure":"A customer moves from Bronze to Gold and every historical sale jumps into the Gold row: Gold looks like it grew 40% last year when nothing happened.","use":"SCD type 2 (new row per change, valid-from/valid-to) for attributes people analyse over time; type 1 (overwrite) for corrections; surrogate keys so versions can coexist.","avoid":"Type 2 on everything. Tracking history on phone numbers or typos bloats the dimension and confuses users."},"verified":{"date":"2026-10-01","context":"Kimball dimensional modeling techniques; portable SQL tested on SQLite in CI","review_after_days":365},"refs":[{"title":"Star schema guidance for Power BI (slowly changing dimensions)","url":"https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"},{"title":"Dimensional modeling in Fabric Data Warehouse: dimension tables","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/dimensional-modeling-dimension-tables"}],"asg":[{"t":"Build an SCD type 2 customer dimension","time":"50 min","ds":"customer_changes","guidance":"B","brief":"The CRM sends a change feed: one row per customer per effective change. Build dim_customer with full history so sales can be analysed by the segment and tier the customer had at the time.","req":["A surrogate key, the natural key (CustomerID), the tracked attributes, ValidFrom, ValidTo and IsCurrent.","Remove exact duplicate feed rows.","Don't create a new version when the CRM sends a \"change\" in which nothing tracked actually changed.","Report the counts."],"exp":"200 feed rows → 1 exact duplicate and 4 no-op changes removed → 195 versions for 122 customers (122 current, 73 historical); 53 customers have more than one version."},{"t":"Which version was true on that day?","time":"30 min","ds":"customer_changes, orders","guidance":"B","brief":"Attach each order to the customer version that was valid on the order date, so sales by tier reflect the tier at the time.","req":["Point-in-time join: OrderDate >= ValidFrom AND OrderDate < ValidTo.","Show the versions of customer C10005.","Decide, per attribute, whether it should be type 1 or type 2."],"exp":"C10005 has 3 versions: from Bronze to Silver, latest change on 2026-02-24. Orders before that date keep the earlier tier."},{"t":"Orders for customers who don't exist yet","time":"40 min","ds":"early_orders, customer_changes","guidance":"C","brief":"Four orders arrived for customers the CRM hasn't sent yet. Last night's load dropped them because the join to dim_customer failed. Fix the design so no fact row is ever lost, and say what happens when the customer arrives later.","req":["Never drop a fact row because a dimension row is missing.","Distinguish \"unknown\" from \"not yet arrived\".","Show which of the four orders can be resolved once the CRM catches up."],"exp":"4 early orders: 3 resolve when their customer arrives (inferred members, updated later); 1 never appears in the feed and stays on the Unknown member until someone investigates."}],"int":[{"q":"Surrogate key vs natural key?","a":"The natural key comes from the source (CustomerID). A surrogate key is a meaningless integer the warehouse assigns. With SCD type 2 one customer has several rows, so the natural key isn't unique; the surrogate key is, and facts point to the version valid at the time. Surrogate keys also protect you from source key changes and mixed sources."},{"q":"SCD type 1 vs type 2?","a":"Type 1 overwrites the attribute: history is lost, which is right for corrections (a misspelt name). Type 2 adds a new row with validity dates: history is kept, which is right for attributes analysed over time (segment, region, tier). Many dimensions mix both per column."},{"q":"What is an unknown member and why add one?","a":"A dimension row (often key -1, \"Unknown\") that facts point to when their dimension key is missing or invalid. Facts are never dropped, totals stay complete, and the unknown row makes data quality problems visible in reports."},{"q":"Early-arriving fact vs late-arriving dimension?","a":"Two names for the same situation: a fact references a dimension member the warehouse doesn't have yet. Create an inferred member (natural key only, attributes \"pending\"), point the fact to it, and update it when the real dimension row arrives."}],"ass":[{"type":"mcq","q":"A customer changes from Bronze to Gold on 1 March. With SCD type 2, a February order is reported under:","o":["Gold","Bronze","Both","Unknown"],"a":1,"why":"The fact points to the version valid on the order date."},{"type":"mcq","q":"Why use a surrogate key instead of CustomerID in a type 2 dimension?","o":["It's shorter","CustomerID isn't unique once a customer has several versions","Power BI requires integers","It hides personal data"],"a":1,"why":"Each version needs its own key."},{"type":"task","q":"In Power BI, relate FactSales to the type 2 dim_customer and build a matrix of sales by LoyaltyTier for 2025 and 2026. Then build the same with only the current version. Explain the difference to a sales manager.","hint":"Join facts on the surrogate key for history; use a separate \"current customer\" view (or the IsCurrent filter on a type 1 copy) for \"as is today\" analysis."}],"module":"warehousing"},{"id":"dw-facts","name":"Fact table types: transaction, snapshot, accumulating, factless","ds":["OrderEvents","FactInventory","NWOrders"],"skills":["warehousing","modeling","sql"],"stage":"engineer","why":{"matters":"The fact type decides which questions are easy and which measures are additive. Inventory, pipelines and fulfilment can't be modelled like sales.","failure":"Weekly stock snapshots are summed across weeks and the warehouse appears to hold ten times its real stock.","use":"Transaction facts for events (sales lines); periodic snapshots for levels measured at intervals (stock, balances); accumulating snapshots for processes with milestones (order to delivery); factless facts for coverage and eligibility.","avoid":"Forcing a process into a transaction fact and reconstructing milestones with complex DAX at query time."},"verified":{"date":"2026-10-01","context":"Kimball fact table techniques; portable SQL tested on SQLite in CI","review_after_days":365},"refs":[{"title":"Dimensional modeling in Fabric Data Warehouse: fact tables","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/dimensional-modeling-fact-tables"}],"asg":[{"t":"Build an accumulating snapshot of fulfilment","time":"45 min","ds":"order_events","guidance":"B","brief":"Operations want to see where March orders spend their time: placed → picked → shipped → delivered. Turn the event log into one row per order with a column per milestone and the lags between them.","req":["One row per order with PlacedAt, PickedAt, ShippedAt, DeliveredAt (NULL if not reached yet).","Hours from placed to shipped; whether it was delivered within 5 days of being placed.","Explain why this table is updated in place, unlike a transaction fact."],"exp":"227 orders; 227 shipped and 226 delivered by the extract date. Average 65.3 hours from placed to shipped; 51% of delivered orders arrived within 5 days."},{"t":"Stock is a snapshot, not a sum","time":"30 min","ds":"FactInventory (course dataset)","guidance":"B","brief":"FactInventory holds weekly stock snapshots. Design the month-end stock figure the finance team needs, and show what goes wrong if someone sums it.","req":["Month-end stock = the last snapshot in each month.","Show the naive sum for comparison.","Name which dimensions stock can and can't be summed over."],"exp":"Month-end stock: January 725, February 516, March 682 units. Summing all 10 snapshots gives 5,791. Stock adds up across products and warehouses but not across time."},{"t":"Choose the fact type","time":"25 min","ds":"—","guidance":"D","brief":"Elena wants designs for four new requests. For each, choose the fact table type and grain, and say which measures are additive.","req":["Customer support tickets from opened to resolved, with SLA breaches.","Monthly account balances for wholesale customers.","Which products were on promotion in which stores, including those that sold nothing.","Every web page view."],"deliverables":["A table: request, fact type, grain, additive measures, semi/non-additive measures."],"exp":"Tickets: accumulating snapshot (one row per ticket). Balances: periodic snapshot (customer × month; semi-additive). Promotion coverage: factless fact (product × store × promotion × day). Page views: transaction fact (one row per view)."}],"int":[{"q":"Name the main fact table types and an example of each.","a":"Transaction (one row per event: a sales line), periodic snapshot (one row per entity per period: month-end balance, weekly stock), accumulating snapshot (one row per process instance updated as milestones happen: order fulfilment), factless (records that something happened or was possible, with no measure: attendance, promotion coverage)."},{"q":"What is a semi-additive measure?","a":"One that can be summed over some dimensions but not others. Stock levels and balances add across products or accounts, but over time you take the last (or average) value, not the sum."},{"q":"Why is an accumulating snapshot updated rather than appended?","a":"Its grain is the process instance (one order). As the order reaches each milestone, the same row gets the new date and lag. Appending would create several rows per order and break the grain."},{"q":"What question can a factless fact answer that a sales fact can't?","a":"What didn't happen: products on promotion that didn't sell, students enrolled who didn't attend. Sales facts only contain what happened, so coverage needs its own table."}],"ass":[{"type":"mcq","q":"Month-end bank balances should be stored as:","o":["A transaction fact","A periodic snapshot","An accumulating snapshot","A factless fact"],"a":1,"why":"A level measured at regular intervals is a periodic snapshot, and it's semi-additive over time."},{"type":"mcq","q":"In an accumulating snapshot of orders, what happens when an order ships?","o":["A new row is inserted","The existing row is updated with ShippedAt and the lag","The row is deleted","Nothing until delivery"],"a":1,"why":"The grain is one row per order; milestones update it."},{"type":"task","q":"In Power BI, build the semi-additive measure Stock On Hand with LASTNONBLANK (see Advanced → semi-additive inventory) and check it against your SQL month-end numbers.","hint":"January 725, February 516, March 682."}],"module":"warehousing"},{"id":"dw-dims","name":"Dimension patterns: conformed, role-playing, junk and bridge","ds":["NWOrders","NWOrderLines","CustomerTargets"],"skills":["warehousing","modeling","dax"],"stage":"developer","why":{"matters":"Shared, well-designed dimensions are what let Sales, Finance and Operations slice different facts by the same customer, product and date, and get comparable answers.","failure":"Each fact gets its own copy of the date table and \"Q1\" means three slightly different things on one dashboard.","use":"Conformed dimensions shared across facts; role-playing for several dates; junk dimensions for scattered flags; bridges for genuine many-to-many.","avoid":"Bridges and bi-directional filters to paper over a grain problem that a better fact design would remove."},"verified":{"date":"2026-10-01","context":"Power BI relationship guidance (role-playing, many-to-many), Sept 2026","review_after_days":365},"refs":[{"title":"Active vs inactive relationship guidance (role-playing dimensions)","url":"https://learn.microsoft.com/en-us/power-bi/guidance/relationships-active-inactive"},{"title":"Many-to-many relationship guidance","url":"https://learn.microsoft.com/en-us/power-bi/guidance/relationships-many-to-many"}],"asg":[{"t":"One date table, three dates","time":"35 min","ds":"orders, order_lines","guidance":"B","brief":"Sales wants Q1 2026 by order date, Operations by ship date, Finance by posting date, all from one model and one date table.","req":["One active relationship (order date) and two inactive ones.","Measures that use USERELATIONSHIP for ship and posting dates.","Compare Q1 2026 gross sales by order date and by ship date, and explain the difference."],"exp":"By order date $254,751; by ship date $255,185. The difference comes from orders placed in late December that shipped in January and March orders that shipped in April."},{"t":"A junk dimension for order flags","time":"25 min","ds":"orders","guidance":"C","brief":"FactSales carries Channel, Status and Currency as text on every row: wasteful at 30 million rows and messy for the field list. Replace them with one small dimension.","req":["Build the dimension from the combinations that actually occur.","Give it a surrogate key and point the fact to it.","Say why a cross join of all possible values may or may not be better."],"exp":"19 combinations occur out of 20 possible. The fact keeps one small integer instead of three text columns."},{"t":"Targets that don't fit the customer grain","time":"35 min","ds":"CustomerTargets, DimCustomer (course datasets)","guidance":"B","brief":"Targets are set by Segment × LoyaltyTier × Quarter, not by customer (course dataset CustomerTargets). Model them so a matrix by Segment and Tier shows actuals and targets side by side.","req":["Either a bridge (Segment-Tier dimension) or relationships at the target grain; explain your choice.","Show what happens at customer level (targets can't be split)."],"exp":"Targets appear at Segment × Tier and above; at customer level they are blank (or repeated, if you chose a *:* relationship, which is why you shouldn't)."}],"int":[{"q":"What is a conformed dimension?","a":"A dimension shared, with the same keys and attributes, by several facts (and ideally several models), so that slicing Sales and Returns by Product gives comparable results. It's the backbone of an enterprise bus matrix."},{"q":"What is a role-playing dimension, and how do you model it in Power BI?","a":"One dimension used in several roles, like Date as order date, ship date and posting date. In Power BI: one active relationship and inactive ones activated per measure with USERELATIONSHIP, or separate copies of the date table when users need to slice by two roles at once."},{"q":"When is a junk dimension useful?","a":"When a fact has several low-cardinality flags or codes that don't belong to any dimension. Combining them into one small dimension replaces several text columns with one key and gives users one tidy place to find them."},{"q":"When do you need a bridge table?","a":"For a genuine many-to-many: an account with several owners, a patient with several diagnoses, or a fact at a grain coarser than a dimension (targets by segment). The bridge resolves the relationship; weighting factors avoid double counting when amounts must be allocated."}],"ass":[{"type":"mcq","q":"Users need a matrix by Order Month AND Ship Month at the same time. Best model?","o":["One date table with USERELATIONSHIP","Two date tables (order date, ship date), each with an active relationship","A bi-directional relationship","A calculated column"],"a":1,"why":"USERELATIONSHIP activates one role per measure; slicing by two roles simultaneously needs two date dimensions."},{"type":"mcq","q":"Targets exist by Segment × Tier. A *:* relationship from targets to customers will, at customer level:","o":["Split the target evenly","Repeat the segment's target for every customer","Show blank","Error"],"a":1,"why":"Each customer in the segment sees the whole target, and totals still work because filters propagate; that's why customer-level target visuals are misleading."},{"type":"task","q":"Draw (or describe) the bus matrix for Northwind: facts as rows (Sales, Returns, Budget, Inventory, Payroll), dimensions as columns (Date, Product, Customer, Region, Employee), with a tick where they relate.","hint":"Budget is at Category × Month, so it relates to a Category-level product dimension and to Date at month grain."}],"module":"warehousing"},{"id":"dw-time","name":"Calendars, time zones and currencies","ds":["WebSessionsLocal","NWOrders","NWOrderLines","NWFx"],"skills":["warehousing","modeling","sql"],"stage":"engineer","why":{"matters":"\"Yesterday\", \"Q1\" and \"in dollars\" each hide a decision. Get them wrong and numbers don't match Finance, regions disagree on daily totals, and currency movements look like sales growth.","failure":"Europe's sales look 4% lower than the German entity reports, because they were translated at the quarter-end rate instead of each month's average.","use":"Store timestamps in UTC with the original offset; build one date dimension with calendar and fiscal (including 4-4-5) columns; keep amounts in transaction currency and translate with an explicit, documented rate rule.","avoid":"Converting time zones or currencies in DAX at query time when it can be done once at load."},"verified":{"date":"2026-10-01","context":"Portable SQL tested on SQLite in CI; Power BI date table guidance, Sept 2026","review_after_days":365},"refs":[{"title":"Date tables in Power BI","url":"https://learn.microsoft.com/en-us/power-bi/guidance/model-date-tables"},{"title":"AT TIME ZONE (Transact-SQL)","url":"https://learn.microsoft.com/en-us/sql/t-sql/queries/at-time-zone-transact-sql"}],"asg":[{"t":"Whose \"7 April\" is it?","time":"30 min","ds":"web_sessions_local","guidance":"B","brief":"Web sessions are logged in the visitor's local time with a UTC offset. Marketing in Berlin and the US teams get different daily totals. Normalise to UTC and show the effect.","req":["Convert StartLocal to UTC using UtcOffset.","Count sessions per day by local date and by UTC date.","Recommend which date the daily report should use, and when local time is still the right choice."],"exp":"34 of 240 sessions fall on a different date in UTC. 7 April 2026 has 60 sessions by local date and 55 by UTC date."},{"t":"Europe in euros and in dollars","time":"30 min","ds":"orders, order_lines, fx_rates","guidance":"B","brief":"Lea (Europe) reports Q1 2026 in euros; the group reports in dollars. Show both, and show what changes if someone translates the quarter at the March rate instead of each month's rate.","req":["Q1 2026 Europe gross in EUR (transaction currency).","The same in USD at each month's average rate (the agreed rule).","The same at the March rate, and the difference."],"exp":"€20,325.12 in EUR. At monthly average rates $22,050; at the March rate $22,004. The difference is FX, not sales."},{"t":"Build the 4-4-5 fiscal calendar","time":"40 min","ds":"orders, order_lines","guidance":"C","brief":"From FY2026 Finance reports on a 4-4-5 calendar that starts on Sunday 28 December 2025 (see the change-request drill). Add the fiscal columns to the date dimension and reproduce Finance's period totals.","req":["FiscalYear, FiscalPeriod (1–12) and FiscalQuarter columns for every date of FY2026.","Gross sales for fiscal periods 1, 2 and 3.","One relationship to the same date table: don't create a second date table."],"exp":"P1 (28 Dec–24 Jan) $103,337, P2 (25 Jan–21 Feb) $60,004, P3 (22 Feb–28 Mar) $95,677; fiscal Q1 $259,018."}],"int":[{"q":"Why store timestamps in UTC?","a":"UTC has no daylight-saving gaps or overlaps and gives one global order of events. Keep the original offset or time zone too, so local-time questions (\"what hour do customers shop?\") can still be answered."},{"q":"What is a 4-4-5 calendar and why do retailers use it?","a":"Each quarter is 13 weeks split into periods of 4, 4 and 5 weeks, always starting on the same weekday. Periods have equal numbers of weekends, so period-on-period comparisons aren't distorted by calendar months of 28 to 31 days."},{"q":"Which exchange rate should a sales report use?","a":"Whatever the finance policy says, written down and applied consistently: commonly the average rate of the month of the transaction for revenue, and the closing rate for balances. Keep the transaction currency amount too, so you can separate sales change from FX change."},{"q":"Where should time-zone and currency conversion happen?","a":"At load time, in the warehouse or view: once, consistently, foldable, and testable. DAX-time conversion makes every query slower and easy to get inconsistent across measures."}],"ass":[{"type":"mcq","q":"A session starts at 23:30 local time in Los Angeles (UTC−07:00) on 6 April. Its UTC date is:","o":["5 April","6 April","7 April","It depends on the server"],"a":2,"why":"23:30 + 7 hours = 06:30 the next day, 7 April UTC."},{"type":"mcq","q":"Q1 sales in EUR were flat but Q1 sales in USD grew 5%. Most likely:","o":["Sales grew in Europe","The euro strengthened against the dollar","A data error","Returns fell"],"a":1,"why":"Same euros, more dollars per euro: that's FX, not sales. Show constant-currency growth alongside."},{"type":"task","q":"In Power BI, add a field parameter or calculation group that switches Gross Sales between transaction currency (EUR for Europe) and USD.","hint":"Keep both amounts as columns at load; the calculation group (Advanced → currency conversion) selects which one to sum."}],"module":"warehousing"}]},
{"id":"testing","kind":"track","order":3,"cls":"qa","name":"Testing and validation","tag":"Track","tagline":"Data quality tests, known-input model tests, security matrices, refresh checks, performance budgets, regression, and a lab where you break things on purpose.","seo":"Testing for Power BI developers: data quality tests, DAX measure tests with known inputs and outputs, RLS test matrices, refresh and performance tests, regression testing and failure-injection exercises.","intro":"In BI, a number is wrong until it's proven right. This track turns \"looks fine\" into tests you can run again after every change: on the data, on the measures, on security, on refresh and on performance. The last topic is a lab where you deliberately break a model, watch what happens and learn to recognise the symptom later.","setup":"Power BI Desktop with DAX query view, the course datasets and starter project, the company pack, and data/tracks/testing/mini_sales.csv (eight rows whose answers you can work out by hand). DAX Studio is optional.","stage":"developer","topics":[{"id":"qa-data","name":"Data quality tests","ds":["NWOrders","NWOrderLines","NWReturns","NWFx","RawOrdersExport"],"skills":["testing","sql","power-query"],"stage":"developer","why":{"matters":"Every report inherits the quality of its data. Tests that run on every load catch duplicates, orphans and impossible values before an executive does.","failure":"A re-run export duplicates 37 lines; nobody notices for a quarter because the totals \"looked about right\".","use":"Uniqueness of keys, non-null required columns, referential integrity, valid ranges, row-count and total reconciliation with the source, and freshness. Run them on every load; fail loudly.","avoid":"Testing only in Power Query by eye. Tests that aren't automated stop being run."},"verified":{"date":"2026-10-01","context":"Portable SQL tested on SQLite in CI; Power Query profiling docs","review_after_days":365},"refs":[{"title":"Data profiling tools in Power Query","url":"https://learn.microsoft.com/en-us/power-query/data-profiling-tools"}],"asg":[{"t":"A data quality suite for the company pack","time":"45 min","ds":"orders, order_lines, returns, fx_rates","guidance":"B","brief":"Write one query (or one script) that runs a set of named data quality tests and returns, for each, the number of failing rows. It must run after every load and be easy to read.","req":["Uniqueness of (OrderID, LineNo) in order_lines.","Referential integrity: lines and returns point to existing orders.","Valid ranges: quantity > 0; returned quantity not above the sold quantity; ship date not before order date.","Every EUR order month has an exchange rate.","Flag test customers."],"exp":"Failures: duplicate line keys 37, orphan lines 0, orphan returns 0, non-positive quantities 0, over-returns 0, ship before order 0, missing FX months 0, test-customer orders 3."},{"t":"Reconcile row counts and totals, source to model","time":"30 min","ds":"RawOrdersExport (course dataset)","guidance":"B","brief":"For the Beginner clean-up of RawOrdersExport, write the reconciliation that proves where every source row went: kept, removed as header or total, or removed as a duplicate.","req":["Row counts at each step.","A check that kept + removed = source.","Where you would put this so it runs on every refresh."],"exp":"30 source rows = 27 kept + 1 report header + 1 TOTAL row + 1 duplicate. A Power Query step or a validation query that compares the counts on every refresh."},{"t":"Which tests should block a release?","time":"20 min","ds":"—","guidance":"D","brief":"Elena asks you to classify data tests into \"block the load\", \"warn and continue\" and \"report weekly\". There is no single right answer: justify yours.","req":["Duplicate keys in a fact.","A dimension member missing for some facts.","A 15% drop in daily row count.","Nulls in an optional column.","A refresh finishing 30 minutes later than usual."],"exp":"A defensible split, e.g. block: duplicate fact keys; warn: missing dimension members (route to Unknown) and a large row-count drop; weekly: nulls in optional columns and refresh duration trends, with reasons tied to business impact."}],"int":[{"q":"Which data quality tests would you always run on a fact table?","a":"Key uniqueness at the declared grain, required columns not null, foreign keys that resolve (or are mapped to Unknown), values in valid ranges, row count and total reconciliation against the source, and freshness (max date)."},{"q":"Where should data quality tests run?","a":"As close to the source as possible (in the warehouse load or the view), so every consumer benefits, and again in the semantic model for the few rules that matter to its measures. Power BI-only checks catch problems late and only for one model."},{"q":"What's the difference between a failed test and a known defect?","a":"A known defect is documented, has an owner and a planned treatment (for example routing to Unknown). A failed test is a surprise. Track known defects explicitly so tests stay green for the right reasons."},{"q":"Why reconcile counts, not just totals?","a":"Totals can match by coincidence (duplicates plus missing rows), and counts tell you which rows went where. Reconcile both at each step."}],"ass":[{"type":"mcq","q":"A fact table's key isn't unique. The safest treatment is:","o":["Ignore it","Fail the load and investigate","Average the duplicates","Remove the key column"],"a":1,"why":"Duplicate fact keys double-count. Stop and find out why before anyone sees the numbers."},{"type":"mcq","q":"Sales lines reference a product that isn't in DimProduct. Best practice:","o":["Drop those lines","Map them to an Unknown product member and report the count","Delete the product dimension","Use a bi-directional relationship"],"a":1,"why":"Never lose facts; make the gap visible and fix the source."},{"type":"task","q":"Add a Data Quality page to your Sprint 01 report: one card per test with its failing-row count, red when above zero.","hint":"Measures like COUNTROWS(FILTER(VALUES(FactSales[LineKey]), CALCULATE(COUNTROWS(FactSales)) > 1)) for duplicates; keep it on a hidden or admin page."}],"module":"testing"},{"id":"qa-model","name":"Semantic model tests: known input, known output","ds":["MiniSales"],"skills":["testing","dax","modeling"],"stage":"developer","why":{"matters":"Measures are code. A small table whose answers you can work out by hand turns \"the total looks plausible\" into a test that fails the moment a measure changes behaviour.","failure":"Someone \"fixes\" time intelligence and YoY silently changes for every month that crosses a year boundary; nobody notices until the annual review.","use":"A mini dataset with hand-computed answers, DAX queries (EVALUATE) that return measure values in specific filter contexts, and a stored expected result to compare against after every change.","avoid":"Testing only on production data, where you don't know the right answer."},"verified":{"date":"2026-10-01","context":"DAX query view (Power BI Desktop, Sept 2026)","review_after_days":180},"refs":[{"title":"DAX query view","url":"https://learn.microsoft.com/en-us/power-bi/transform-model/dax-query-view"},{"title":"EVALUATE statement","url":"https://learn.microsoft.com/en-us/dax/evaluate-statement-dax"}],"asg":[{"t":"Work the answers out by hand first","time":"30 min","ds":"mini_sales","guidance":"A","steps":["Open mini_sales.csv: eight lines. Value = Qty × UnitPrice. L8 is a return (negative quantity).","On paper, compute: total sales; Q1 2025; Q1 2026 by order date; Q1 2026 by ship date; YoY for Q1; distinct customers in 2026 and in March 2026; Online sales in Q1 2026.","Load the file into a new Power BI file with a date table: an active relationship on OrderDate, an inactive one on ShipDate.","Write the measures: Sales, Sales (ship date) with USERELATIONSHIP, Sales PY, YoY %, Customers.","Compare every measure with your paper answers."],"exp":"Total 1,800; Q1 2025 350; Q1 2026 1,450 by order date and 1,400 by ship date; YoY 314.3%; 4 customers in 2026, 3 in March 2026; Online Q1 2026 600."},{"t":"Turn them into a DAX test query","time":"30 min","ds":"mini_sales","guidance":"B","brief":"Write one DAX query that returns each test's name, expected value, actual value and pass/fail, so anyone can rerun the whole suite in seconds after a change.","req":["One row per test, including the inactive-relationship and year-boundary cases.","Expected values typed in from your paper answers, not copied from the measures.","A pass flag that tolerates rounding."],"exp":"Every row shows Pass. Change Sales PY to use DATEADD(…, -12, MONTH) incorrectly on purpose and at least the YoY test fails."},{"t":"What should a measure return here?","time":"25 min","ds":"mini_sales","guidance":"C","brief":"Total rows and edge cases are where measures break. Decide what each measure should return in four awkward contexts, test it, and fix what's wrong.","req":["YoY % for a month with no sales last year.","Customers at the grand total (is it the sum of the months?).","Sales for a product filtered to a date range with only a return.","Sales (ship date) for March 2026, when one March order ships in April."],"exp":"YoY blank (not infinity or 0) without prior-year sales; customers at the total = distinct across the period, not the sum of months; the return-only context shows a negative number; ship-date March excludes the line shipped in April."}],"int":[{"q":"What is a known-input, known-output test for a measure?","a":"A small dataset where you've worked out the correct results by hand, and a query that evaluates the measure in specific filter contexts and compares with those results. If the measure or the model changes behaviour, the test fails."},{"q":"Which contexts most often break measures?","a":"Totals (non-additive measures), year and period boundaries (time intelligence), blank or missing data (division, YoY), negative values (returns), inactive relationships and many-to-many paths."},{"q":"How do you run model tests automatically?","a":"Store the test queries (DAX) and expected results in the repository; run them with DAX query view by hand, or automatically through the XMLA endpoint or the executeQueries REST API after deployment, and fail the pipeline on mismatches."},{"q":"Why type expected values in instead of computing them with another measure?","a":"Computing them with DAX can reproduce the same mistake. Independent expected values (by hand, SQL or Excel) are what make it a test."}],"ass":[{"type":"mcq","q":"Your DAX test says YoY for January 2026 = blank. January 2025 had no sales. Is that right?","o":["No, it should be 0%","Yes: there is no prior value to compare with","No, it should be 100%","It should be infinity"],"a":1,"why":"DIVIDE returns blank when the denominator is blank or zero, which is the honest answer."},{"type":"mcq","q":"The distinct customer count for Q1 is lower than the sum of the three months. This means:","o":["A bug","Some customers bought in more than one month","The date table is wrong","Customers were deleted"],"a":1,"why":"Distinct counts are non-additive."},{"type":"task","q":"Store your DAX test query and its expected output in the repository next to the PBIP, and write a one-paragraph README on how to run it.","hint":"Later, the automation track shows how to run it against the Service with the executeQueries REST API."}],"module":"testing"},{"id":"qa-security","name":"Security tests","ds":["UserRegionMapping","FactSales","DimRegion"],"skills":["testing","security"],"stage":"developer","why":{"matters":"Security that isn't tested is a hope. An RLS test matrix with expected numbers per user is the only evidence Compliance can rely on, and it catches regressions when someone changes a relationship.","failure":"A relationship is made inactive to fix an ambiguity; RLS silently stops reaching one fact table (Sprint 03).","use":"A matrix of users × roles × expected visible data, run with View as (or DAX queries executed as the user) on every release, including tools that bypass the report.","avoid":"Checking that the report \"looks filtered\". Page filters and hidden visuals aren't security."},"verified":{"date":"2026-10-01","context":"RLS and OLS testing docs (View as roles), Sept 2026","review_after_days":180},"refs":[{"title":"Validate roles in Power BI Desktop and the service","url":"https://learn.microsoft.com/en-us/fabric/security/service-admin-row-level-security"},{"title":"RLS guidance","url":"https://learn.microsoft.com/en-us/power-bi/guidance/rls-guidance"}],"asg":[{"t":"An RLS test matrix with expected numbers","time":"40 min","ds":"UserRegionMapping, FactSales, DimRegion","guidance":"B","brief":"Using the dynamic RLS from Intermediate (UserRegionMapping with USERPRINCIPALNAME), write and run a test matrix that would satisfy Compliance.","req":["Every user in the mapping table plus one user who isn't in it.","Expected net sales per user, computed independently (SQL or Excel), not from the report.","Actual result with View as, and pass/fail."],"exp":"Dana $12,164.13, Marcus $3,634.46, Nina (West + East) $17,863.94, Grace (All) $33,391.13; the unmapped user sees nothing. 11 users and 12 mapping rows in total."},{"t":"Break the security on purpose","time":"30 min","ds":"starter project","guidance":"C","brief":"Make three changes that a well-meaning colleague might make, rerun your matrix after each, and record which ones it catches: make a relationship bi-directional, make the Region relationship inactive, and remove a user's row from the mapping table.","req":["Record the matrix result after each change.","Add a test that would have caught anything your matrix missed."],"exp":"Inactive relationship: every regional user sees all regions (caught). Removed mapping row: that user sees nothing (caught only if every user is in the matrix). Bi-directional relationship: filters can leak into other tables; caught only if the matrix also checks a dimension list or another fact."},{"t":"Test what the report hides","time":"20 min","ds":"starter project","guidance":"B","brief":"Show that page filters and hidden visuals aren't security, and add tests that use the tools a user with Build permission has.","req":["Test with Analyze in Excel or a new report on the model, not just the published report.","Test object-level security (a hidden Salary column) separately from RLS."],"exp":"The page filter disappears in Analyze in Excel; RLS still applies; OLS makes the column not exist for the restricted role (visuals using it error)."}],"int":[{"q":"How do you test RLS?","a":"View as role (and as a specific user for dynamic RLS) in Desktop and the Service, with a matrix of users, expected visible rows or totals computed independently, and actual results. Include a user with no role, a user with two roles, and tools that bypass report filters."},{"q":"What happens when a user is in two roles?","a":"Roles are additive: the user sees the union of what each role allows. Test multi-role users explicitly, because adding a broad role to someone can quietly widen their access."},{"q":"Does RLS apply to workspace Admins, Members and Contributors?","a":"No. RLS applies to users with Viewer role (or app/sharing access). Workspace Admins, Members and Contributors can see all data in the model, so keep them few and don't use workspace roles for consumers."},{"q":"Why aren't page filters security?","a":"They're part of the report definition. Anyone with Build permission, Analyze in Excel or a new report on the same model doesn't see them. Only roles in the model (RLS/OLS) are enforced by the engine."}],"ass":[{"type":"mcq","q":"A report author is a workspace Member. With RLS on the model, they see:","o":["Only their region","All data: RLS doesn't apply to Members","Nothing","Only aggregated data"],"a":1,"why":"RLS only restricts Viewers and users accessing through apps or sharing."},{"type":"mcq","q":"A user is in the West role and the East role. They see:","o":["West only","East only","West and East","Neither"],"a":2,"why":"Roles combine as a union."},{"type":"task","q":"Write the security matrix for Sprint 03 (payroll) as a reusable template your team can apply to any model.","hint":"Columns: user, role(s), should see, must not see, sensitive objects visible?, test query, expected, actual, pass. See Templates → RLS / OLS test matrix."}],"module":"testing"},{"id":"qa-ops","name":"Refresh tests, performance budgets and regression","ds":["FactSales","DimDate"],"skills":["testing","performance","service","deployment"],"stage":"senior","why":{"matters":"Most production incidents aren't wrong DAX; they're refreshes that succeeded with the wrong data, pages that got slower one measure at a time, or a fix that broke something else.","failure":"A refresh reports Completed with a warning for weeks while one table is stale (Sprint 07).","use":"Post-refresh checks (rows, max date, partitions), a written performance budget measured the same way every release, and a regression baseline of key numbers compared before and after each change.","avoid":"Treating \"refresh succeeded\" as \"data is right\"."},"verified":{"date":"2026-10-01","context":"Refresh history, incremental refresh and Performance Analyzer docs, Sept 2026","review_after_days":180},"refs":[{"title":"Troubleshoot refresh scenarios","url":"https://learn.microsoft.com/en-us/power-bi/connect-data/refresh-troubleshooting-refresh-scenarios"},{"title":"Incremental refresh overview","url":"https://learn.microsoft.com/en-us/power-bi/connect-data/incremental-refresh-overview"},{"title":"Performance Analyzer","url":"https://learn.microsoft.com/en-us/power-bi/create-reports/performance-analyzer"}],"asg":[{"t":"Post-refresh checks","time":"30 min","ds":"FactSales, DimDate (course)","guidance":"B","brief":"Write the checks that should run after every refresh of the course model, so a stale or partial load is caught before users see it.","req":["Row count of FactSales against the source file.","Max OrderDate against the expected data date.","No blank keys after load; every FactSales date exists in the date table.","For incremental refresh: the partitions you expect exist (DAX INFO functions or XMLA)."],"deliverables":["A DAX query returning check name, expected, actual, pass."],"exp":"FactSales has 100 rows, max OrderDate 2026-03-31, no blank keys; the course DimDate fails the date coverage check (one ship date in April), which is exactly why Beginner replaces it."},{"t":"Write and enforce a performance budget","time":"30 min","ds":"starter project","guidance":"C","brief":"Elena wants a performance budget for the executive page so Sprint 04 never happens again. Define it, measure it the same way every time, and say what happens when a change breaks it.","req":["Budgets for cold page load, slicer interaction, refresh duration and model size.","The measurement method (cache, machine, tool).","What blocks a release and what only warns."],"exp":"For example: page < 3 s cold, slicer < 1 s, refresh < 30 min, model < 1 GB, measured with Performance Analyzer after clearing the cache on the test machine; a breach of page or slicer budget blocks the release, others warn."},{"t":"Prove you didn't break anything else","time":"30 min","ds":"starter project","guidance":"B","brief":"Before changing the Net Sales definition (Sprint 02's ledger change), capture a regression baseline, make the change, and prove that only the intended numbers moved.","req":["A baseline: a DAX query returning ten key measures by month, saved to a file.","The same query after the change; a comparison listing every difference.","An explanation for each difference (expected or not)."],"exp":"Only the measures depending on Net Sales change, by exactly the amounts in the change's impact assessment; Gross Sales, quantities and counts are identical."}],"int":[{"q":"Refresh succeeded but the numbers are wrong. What do you check?","a":"Which source each table actually read (parameters, connections), row counts and max dates against the source, refresh warnings (tables that kept old data), incremental refresh partitions, and whether an upstream job ran before the refresh."},{"q":"What is a performance budget?","a":"Agreed limits (page load, interaction, refresh, model size) measured the same way every time. It turns \"feels slow\" into a release criterion and stops gradual degradation."},{"q":"What is a regression test in BI?","a":"A comparison of key outputs before and after a change, proving that only the intended numbers moved. Save a baseline query result; rerun it after the change; explain every difference."},{"q":"How do you check incremental refresh is working?","a":"Look at the partitions (XMLA, SSMS, Tabular Editor, or DAX INFO functions), confirm only the latest partitions refresh, compare refresh duration with a full refresh, and check that the source filter folds (native query contains the RangeStart/RangeEnd predicate)."}],"ass":[{"type":"mcq","q":"A refresh history shows Completed with a warning that a table wasn't refreshed. You should:","o":["Ignore it; it completed","Treat it as a failure for production models and alert the owner","Restart the gateway","Delete the table"],"a":1,"why":"Stale data that looks fresh is worse than a failure."},{"type":"mcq","q":"Which measurement is comparable across releases?","o":["Whatever the developer saw on their laptop","Performance Analyzer after clearing the cache, same machine and dataset","User feelings","Refresh time on a busy capacity"],"a":1,"why":"Same method, same conditions; otherwise you compare noise."},{"type":"task","q":"Write your team's release checklist section \"Tests\" (data, model, security, performance, regression) in five lines.","hint":"See Templates → Deployment checklist and Validation."}],"module":"testing"},{"id":"qa-break","name":"Build it, break it: the failure lab","ds":["FactSales","DimCustomer","DimRegion","DimProduct"],"skills":["testing","performance","modeling","dax"],"stage":"senior","why":{"matters":"You recognise a failure quickly only if you've seen it before. Breaking a model on purpose, in a safe copy, builds that recognition without waiting for a production incident.","failure":"A team spends two days on a \"random\" wrong total that anyone who had seen bi-directional ambiguity would have spotted in minutes.","use":"For each failure: build the working version, break it deliberately, observe the symptom, diagnose it with tools, fix it, explain it in two sentences, and write the check that prevents it.","avoid":"Doing this on a shared or production model. Always work on a copy."},"verified":{"date":"2026-10-01","context":"Power BI Desktop (Sept 2026): relationships, Performance Analyzer, View Native Query, incremental refresh","review_after_days":180},"refs":[{"title":"Bi-directional relationship guidance","url":"https://learn.microsoft.com/en-us/power-bi/guidance/relationships-bidirectional-filtering"},{"title":"Query folding guidance","url":"https://learn.microsoft.com/en-us/power-query/query-folding-basics"},{"title":"Data reduction techniques for Import models","url":"https://learn.microsoft.com/en-us/power-bi/guidance/import-modeling-data-reduction"}],"asg":[{"t":"Break the relationships","time":"45 min","ds":"starter project","guidance":"B","brief":"In a copy of the starter project, make the relationships misbehave in two ways and learn the symptoms.","req":["Build: Net Sales by RegionName from DimRegion and by the customer's region, as in Beginner.","Break 1: set DimCustomer ↔ FactSales to bi-directional and add DimCustomer[RegionKey] → DimRegion. Observe what Power BI does and what your visuals show.","Break 2: make FactSales → DimRegion inactive. Observe the totals.","For each: the symptom, how you diagnosed it, the fix, a two-sentence explanation, and the check that would have caught it."],"exp":"Break 1: Power BI refuses or deactivates a relationship because of an ambiguous path (or results depend on which path wins). Break 2: every region shows the grand total. Checks: no bi-directional relationships without an ADR; a test that regional totals sum to the grand total and differ from each other."},{"t":"Break the performance","time":"45 min","ds":"enterprise pack (1M rows) or starter project","guidance":"B","brief":"Generate a larger fact (Resources → Enterprise scale pack) and make it slow on purpose, three ways, measuring each with Performance Analyzer and DAX Studio.","req":["An iterator that evaluates a measure per row of the fact (e.g. SUMX(FactSales, [Net Sales]) or FILTER over the fact with a measure inside).","A calculated column on the fact with a high-cardinality result (e.g. a timestamp as text).","A query that stops folding (a custom function per row before a filter)."],"exp":"The iterator shows many storage-engine queries or callbacks and FE time; the calculated column inflates model size (VertiPaq Analyzer) and refresh; the broken folding shows a greyed-out View Native Query and a longer refresh. Each fix restores the baseline."},{"t":"Break the refresh","time":"30 min","ds":"starter project","guidance":"C","brief":"Simulate the two most common refresh failures and write the runbook entry for each.","req":["Schema drift: rename a column in a source CSV that the model uses.","Incremental refresh misconfigured: RangeStart/RangeEnd filter on a column that doesn't fold, or with >= on both ends.","For each: the error or symptom, the diagnosis, the fix, the prevention."],"exp":"Schema drift: \"The column … wasn't found\" naming the table; fix the step or the source; prevent with a data contract. Incremental: duplicated or missing rows at partition boundaries (>= on both ends) or a full scan every refresh (no folding); fix with >= RangeStart and < RangeEnd on a foldable column."}],"int":[{"q":"Why break things on purpose?","a":"So that you recognise the symptom quickly when it happens for real. The second time you see an ambiguous relationship or a broken fold, you diagnose it in minutes instead of days."},{"q":"What symptom suggests an ambiguous relationship path?","a":"Power BI refusing to activate a relationship, a relationship silently made inactive, or totals that change depending on which filters are applied, especially after adding a bi-directional relationship."},{"q":"Why does >= RangeStart AND <= RangeEnd break incremental refresh?","a":"Rows exactly on the boundary match two adjacent partitions and are loaded twice. Use >= RangeStart AND < RangeEnd so each row belongs to exactly one partition."},{"q":"What is schema drift and how do you defend against it?","a":"A source changes structure (renamed, removed or retyped columns). Defend with data contracts and change notification, select columns by name explicitly, fail loudly with a clear error, and monitor refresh failures."}],"ass":[{"type":"mcq","q":"Making FactSales → DimRegion inactive, with no other change, makes a matrix by RegionName show:","o":["Correct values","The grand total on every row","Blanks","An error"],"a":1,"why":"Without an active path, the region filter doesn't reach the fact, so every row shows the total."},{"type":"mcq","q":"View Native Query is greyed out on a Power Query step against SQL Server. This means:","o":["The query is fast","Folding stopped at or before this step","The step has an error","The source is a file"],"a":1,"why":"Steps after a non-foldable step run in the mashup engine."},{"type":"task","q":"Write a one-page \"failure field guide\": for each failure from this lab, symptom → likely cause → first diagnostic step.","hint":"This is the start of your team's runbook (Templates → Runbook)."}],"module":"testing"}]},
{"id":"automation","kind":"track","order":4,"cls":"api","name":"Automation and APIs","tag":"Track","tagline":"REST APIs with service principals, tenant inventory, refresh automation, XMLA, TOM, TMSL and Tabular Editor scripting.","seo":"Power BI and Fabric automation practice: REST APIs, service principals, workspace inventory, refresh automation and monitoring, executeQueries, XMLA endpoint, TOM, TMSL and Tabular Editor scripts.","intro":"Once a team owns more than a handful of models, clicking stops scaling. This track covers the APIs and scripts BI engineers use to inventory a tenant, trigger and monitor refreshes, run tests and change models in bulk. You don't need a tenant: the files in data/tracks/automation are realistic API responses, so you can build and check your scripts offline, then point them at a real tenant when you have one.","setup":"Python 3 (requests, msal) or PowerShell 7 (MicrosoftPowerBIMgmt module). Optional: a Fabric trial tenant with an app registration. Never commit secrets: use environment variables or a key vault.","stage":"engineer","topics":[{"id":"api-rest","name":"REST APIs, service principals and a tenant inventory","ds":["ApiGroups","ApiDatasets","ApiReports","ApiRefreshes","ApiViews"],"skills":["automation","governance","security"],"stage":"engineer","why":{"matters":"You can't govern what you can't see. A scripted inventory answers \"what do we have, who owns it, is it used, is it healthy\" in minutes, every week, without asking anyone.","failure":"An inventory script authenticates with a developer's personal account; when they leave, it stops, and nobody notices for a month.","use":"A service principal (app registration) in a security group allowed by the tenant settings, least-privilege workspace access, secrets outside the code, and the Power BI or Fabric REST APIs (admin APIs or the scanner API for tenant-wide views).","avoid":"Hard-coded secrets, personal credentials, and admin APIs when workspace-level permissions would do."},"verified":{"date":"2026-10-01","context":"Fabric developer tenant settings (Microsoft Learn, updated 2026-09-29); Power BI REST API reference","review_after_days":120},"refs":[{"title":"Developer admin settings (service principals)","url":"https://learn.microsoft.com/en-us/fabric/admin/service-admin-portal-developer"},{"title":"Power BI REST API: Groups","url":"https://learn.microsoft.com/en-us/rest/api/power-bi/groups"},{"title":"Run metadata scanning (scanner API)","url":"https://learn.microsoft.com/en-us/fabric/governance/metadata-scanning-overview"},{"title":"Microsoft Fabric REST API","url":"https://learn.microsoft.com/en-us/rest/api/fabric/articles/"}],"asg":[{"t":"Build a workspace inventory from API responses","time":"45 min","ds":"groups.json, datasets.json, reports.json, refreshes.json, activity_views.json","guidance":"B","brief":"Write a script that turns the API responses into one inventory table: workspace, semantic model, owner, reports, last refresh status, endorsement, and whether each report was viewed in the last 90 days.","req":["Read the five JSON files (they have the same shape as the real API responses).","One row per report, with its model and workspace.","Summary counts for the governance review.","Structure it so the file-reading part can be swapped for real API calls."],"exp":"5 workspaces, 11 semantic models, 18 reports. 7 reports had no views in 90 days; 6 models have no endorsement (2 certified); 1 model's latest refresh failed."},{"t":"Set up a service principal properly","time":"30 min","ds":"—","guidance":"B","brief":"Write the setup checklist your team will follow to give the inventory script its own identity instead of a person's account.","req":["App registration and client secret or certificate, and where the secret lives.","Security group, and the tenant settings that must allow it.","Workspace access (which role, which workspaces) or read-only admin API access, and why.","Token request: authority, scope and flow."],"exp":"An app registration in an allowed security group; \"Service principals can call Fabric public APIs\" enabled for that group (plus read-only admin API access only if you need tenant-wide data); Viewer or Member access only on the workspaces it inventories; secret in a key vault or pipeline secret, never in code; client-credentials flow with scope https://analysis.windows.net/powerbi/api/.default."},{"t":"The secret in the repository","time":"20 min","ds":"—","guidance":"C","brief":"Sam pushed the inventory script to the team's GitHub repository with the client secret in a variable. The repository is internal, but 40 people can read it. What do you do, in order?","req":["Containment first.","Clean-up of the repository and its history.","Prevention."],"exp":"Rotate (revoke) the secret immediately, check sign-in logs for the app, then remove it from code and history (and treat it as compromised regardless), move it to a secret store, and add secret scanning and a pre-commit hook. Rewriting history alone isn't enough: the secret was already exposed."}],"int":[{"q":"What is a service principal and why use one for automation?","a":"The identity of an app registration in Microsoft Entra ID. Automation runs as the app, not as a person, so it doesn't break when someone leaves, its permissions can be limited precisely, and its actions are auditable."},{"q":"Which tenant settings control service principals in Fabric?","a":"Under Developer settings: \"Service principals can call Fabric public APIs\" (CRUD on items protected by the Fabric permission model) and \"Service principals can create workspaces, connections, and deployment pipelines\". Both can be limited to security groups. Read-only admin APIs have their own admin API setting."},{"q":"Admin APIs vs regular APIs?","a":"Regular APIs see what the identity has access to (its workspaces). Admin APIs and the scanner API see the whole tenant and need admin rights or read-only admin API permission. Use the narrowest one that answers the question."},{"q":"How would you inventory every workspace in a large tenant?","a":"The scanner API: list modified workspaces, request scans in batches (getInfo), poll scanStatus, then fetch scanResult with lineage and datasource details. It's built for tenant-wide metadata without calling per-item APIs thousands of times."}],"ass":[{"type":"mcq","q":"Your inventory script should authenticate with:","o":["The BI lead's account","A service principal in an allowed security group, secret in a key vault","A shared password in the script","Anonymous access"],"a":1,"why":"An app identity with least privilege, and secrets outside code."},{"type":"mcq","q":"To read metadata for every workspace in the tenant efficiently, use:","o":["GET /groups for each user","The admin scanner API (getInfo, scanStatus, scanResult)","Export to Excel from the portal","XMLA on each model"],"a":1,"why":"The scanner API is designed for tenant-wide metadata in batches."},{"type":"task","q":"Extend your inventory with each model's data sources and gateway (datasources endpoint, or the scanner API's datasourceInstances).","hint":"GET /groups/{groupId}/datasets/{datasetId}/datasources; group sources by server to see which models depend on which systems."}],"module":"automation"},{"id":"api-refresh","name":"Refresh automation, monitoring and tests through the API","ds":["ApiRefreshes","ApiDatasets"],"skills":["automation","service","testing"],"stage":"engineer","why":{"matters":"Refreshes should run after upstream data is ready, not at a fixed time that hopes it is; and failures should reach a team, not one person's inbox.","failure":"A 05:30 schedule runs before the warehouse load finishes on busy days, and reports show yesterday's data with no error at all.","use":"Trigger refresh from the pipeline that loads the data, poll the status with backoff, log every run, alert on failure, and run test queries after success.","avoid":"Tight polling loops (you'll hit API limits) and retrying a failing refresh forever."},"verified":{"date":"2026-10-01","context":"Power BI REST API: Refresh Dataset, Get Refresh History, Execute Queries; enhanced refresh docs","review_after_days":120},"refs":[{"title":"Enhanced refresh with the Power BI REST API","url":"https://learn.microsoft.com/en-us/power-bi/connect-data/asynchronous-refresh"},{"title":"Datasets - Get Refresh History In Group","url":"https://learn.microsoft.com/en-us/rest/api/power-bi/datasets/get-refresh-history-in-group"},{"title":"Datasets - Execute Queries In Group","url":"https://learn.microsoft.com/en-us/rest/api/power-bi/datasets/execute-queries-in-group"}],"asg":[{"t":"Trigger a refresh and poll until it finishes","time":"40 min","ds":"refreshes.json","guidance":"B","brief":"Write a script that refreshes one semantic model, waits for the result without hammering the API, and logs the outcome. Then use the mock refresh history to report the failure rate.","req":["POST the refresh, read the request id, poll the refresh history with increasing waits, stop on Completed, Failed or a timeout.","Log start, end, duration, status and error details.","From refreshes.json: total runs, failed runs, and the model that failed most."],"exp":"13 of 77 runs in the mock history failed. The script polls with backoff, exits non-zero on failure so the calling pipeline fails too, and writes one log line per run."},{"t":"Run the model tests after every refresh","time":"30 min","ds":"—","guidance":"B","brief":"Your known-input tests from the testing track run in DAX query view. Run them automatically after each refresh with the Execute Queries API, and fail the pipeline if any test fails.","req":["POST a DAX query to executeQueries; parse the JSON result.","Compare each test's actual and expected value.","Know the API's limits (one query per call, row limits) and permissions (Build on the model)."],"exp":"A script that posts the test query, reads results.tables[0].rows, fails on any row where Pass is false, and is called after a successful refresh."},{"t":"Design tenant-wide refresh monitoring","time":"30 min","ds":"refreshes.json, datasets.json","guidance":"C","brief":"Elena wants to know about any failed refresh of a certified model within 15 minutes, and a weekly view of refresh duration trends. Design it.","req":["Where the data comes from (APIs, workspace monitoring, capacity metrics).","How alerts are routed (team, severity).","How you avoid alert fatigue."],"exp":"A scheduled job (every 15 minutes) that reads refresh history for certified models and alerts a team channel on Failed or Completed-with-warning; a weekly report of duration trends; severity from the model's endorsement and consumers; suppression of repeats."}],"int":[{"q":"How do you trigger and track a refresh through the REST API?","a":"POST /groups/{groupId}/datasets/{datasetId}/refreshes (optionally with an enhanced-refresh body for specific tables or partitions); then GET the refresh history (or the specific request with enhanced refresh) until the status is Completed or Failed, polling with backoff."},{"q":"What is enhanced refresh?","a":"An asynchronous refresh through the REST API with options: refresh specific tables or partitions, set commit mode, retry count and timeout, and track or cancel the specific request. Useful for orchestration and large models."},{"q":"Why trigger refresh from the data pipeline instead of a schedule?","a":"The refresh then runs when the data is actually ready. A fixed schedule either waits too long or runs too early on slow days and silently shows stale data."},{"q":"What does the Execute Queries API allow?","a":"Running a DAX query against a semantic model and getting the result as JSON. It's handy for automated tests and monitoring, within its limits on rows and query count, and it requires Build permission (and respects RLS for the caller)."}],"ass":[{"type":"mcq","q":"Your script polls refresh status every second. What's the risk?","o":["None","Hitting API rate limits (HTTP 429) and being throttled","The refresh becomes slower","The model is locked"],"a":1,"why":"Poll with increasing waits and respect Retry-After headers."},{"type":"mcq","q":"A refresh status is Completed but a table kept old data because of a credential problem. Your monitoring should:","o":["Treat it as success","Treat warnings on production models as failures","Ignore warnings","Restart the capacity"],"a":1,"why":"Stale-but-green is the most dangerous state (Sprint 07)."},{"type":"task","q":"Add your refresh script to a pipeline (Fabric pipeline, Azure DevOps or GitHub Actions) after the step that loads the warehouse.","hint":"Pass workspace and model IDs as variables; keep the secret in the pipeline's secret store."}],"module":"automation"},{"id":"api-xmla","name":"XMLA, TOM, TMSL and Tabular Editor scripting","ds":[],"skills":["automation","deployment","governance"],"stage":"engineer","why":{"matters":"Model-wide changes (descriptions on 200 measures, format strings, partitions, a new calculation group) are slow and error-prone by hand. Scripts make them repeatable and reviewable.","failure":"Someone renames twenty measures by hand in production through XMLA; three are misspelt, and the PBIX can no longer be downloaded to check.","use":"Tabular Editor scripts or TOM in a pipeline for bulk metadata changes on the PBIP in Git; TMSL or XMLA for partition refreshes and deployments; INFO DAX functions to inspect metadata.","avoid":"Editing production models directly through XMLA outside the release process."},"verified":{"date":"2026-10-01","context":"XMLA endpoint, TOM and INFO DAX functions docs (Microsoft Learn, Sept 2026); Tabular Editor 2","review_after_days":120},"refs":[{"title":"Semantic model connectivity with the XMLA endpoint","url":"https://learn.microsoft.com/en-us/fabric/enterprise/powerbi/service-premium-connect-tools"},{"title":"Tabular Object Model (TOM)","url":"https://learn.microsoft.com/en-us/analysis-services/tom/introduction-to-the-tabular-object-model-tom-in-analysis-services-amo"},{"title":"INFO.MEASURES (DAX)","url":"https://learn.microsoft.com/en-us/dax/info-measures-function-dax"},{"title":"Tabular Model Scripting Language (TMSL) refresh command","url":"https://learn.microsoft.com/en-us/analysis-services/tmsl/refresh-command-tmsl"}],"asg":[{"t":"Find every measure without a description","time":"20 min","ds":"starter project with your measures","guidance":"A","steps":["Open DAX query view in Power BI Desktop on a model with at least ten measures.","Run EVALUATE INFO.MEASURES() and look at the columns it returns.","Filter to measures whose Description is blank; return table name, measure name and expression.","Save the query in the repository as a governance check."],"exp":"A query listing every measure without a description, ready to run on any model (or through executeQueries in a pipeline)."},{"t":"Add descriptions in bulk from the KPI dictionary","time":"40 min","ds":"your KPI dictionary (CSV)","guidance":"B","brief":"Your KPI dictionary (Sprint 01–05) lives in a CSV with MeasureName and Description. Write a script that applies the descriptions to the model, reports measures missing from the dictionary, and never overwrites a description someone wrote by hand without saying so.","req":["Tabular Editor C# script or TOM.","A dry-run mode that only reports what would change.","Run against the PBIP (via Tabular Editor) and commit the result through a pull request."],"exp":"Matched measures get descriptions; unmatched names are listed; overwrites are reported in the dry run; the change is a reviewable diff in the TMDL files."},{"t":"Refresh only what changed","time":"30 min","ds":"a model with incremental refresh on an F or PPU capacity (or the trial)","guidance":"C","brief":"A correction was loaded into the warehouse for March 2026 only. Refresh just that partition of FactSales, not the whole model, and prove that nothing else was reprocessed.","req":["Find the partition name (SSMS, Tabular Editor or INFO.PARTITIONS()).","Refresh it with TMSL through the XMLA endpoint (or enhanced refresh via REST).","Show the refresh time compared with a full refresh."],"exp":"A TMSL refresh command targeting FactSales' 2026 Q1 (or March) partition, a refresh that takes a fraction of the full refresh, and partition metadata showing only that partition's refresh time changed."}],"int":[{"q":"What is the XMLA endpoint?","a":"The Analysis Services protocol endpoint of a workspace on Fabric/Premium capacity (or PPU). Tools like SSMS, Tabular Editor, DAX Studio and scripts use it to read and (with read-write enabled) change semantic models: metadata, partitions, refresh, deployment."},{"q":"TOM vs TMSL vs TMDL?","a":"TOM is the .NET object model for programmatic changes. TMSL is a JSON command language (create, alter, refresh) sent over XMLA. TMDL is the human-readable text format for model definitions, used in PBIP files and Git."},{"q":"What's the risk of changing a published model through XMLA?","a":"The change bypasses source control and review, the model may no longer be downloadable as .pbix, and the next deployment from Git can overwrite it. Make bulk changes in the PBIP (with Tabular Editor) and deploy through the pipeline."},{"q":"How do INFO DAX functions help governance?","a":"INFO.MEASURES(), INFO.TABLES(), INFO.RELATIONSHIPS(), INFO.PARTITIONS() and similar return model metadata as tables in DAX query view, so governance checks (missing descriptions, bi-directional relationships, partition state) are just queries."}],"ass":[{"type":"mcq","q":"To refresh one partition of a large model, use:","o":["Publish the PBIX again","A TMSL refresh command (or enhanced refresh) targeting that partition","Delete the table","Scheduled refresh"],"a":1,"why":"Partition-level refresh through XMLA or enhanced refresh avoids reprocessing everything."},{"type":"mcq","q":"Where should bulk metadata changes (descriptions on 200 measures) be made?","o":["Directly in production via XMLA","In the PBIP in Git with a script, then deployed through the pipeline","By hand in the Service","In Excel"],"a":1,"why":"Reviewable, repeatable, and not overwritten by the next deployment."},{"type":"task","q":"Write a Best Practice Analyzer rule (JSON) that flags measures without a description, and run it in Tabular Editor.","hint":"Scope: Measure; expression: string.IsNullOrWhitespace(Description). Add it to the team's BPA rule file in the repository."}],"module":"automation"}]},
{"id":"governance","kind":"track","order":5,"cls":"gov","name":"Governance","tag":"Track","tagline":"Workspaces, domains and ownership; endorsement; sensitivity labels, OLS and export controls; monitoring, lineage and retirement.","seo":"Power BI and Fabric governance practice: workspace strategy, domains, ownership, endorsement and certification, sensitivity labels, object-level security, export and tenant settings, usage monitoring, lineage and report retirement.","intro":"Governance done well is invisible: people find the trusted model first, sensitive data stays where it should, and unused content quietly disappears. Done badly it's a gate everyone routes around. This track is about the light-touch version that works, practised on Northwind's tenant from Sprint 10.","setup":"A Power BI or Fabric trial tenant helps for the Service steps, but every assignment has evidence files (data/experience/s10 and data/tracks/automation) so you can do the analysis without one.","stage":"architect","topics":[{"id":"gov-workspace","name":"Workspaces, domains, ownership and endorsement","ds":[],"skills":["governance","service","architecture"],"stage":"architect","why":{"matters":"Workspace structure and endorsement decide where people look for data and which numbers they trust. Without them, every team builds its own copy.","failure":"Nineteen models, five customer tables and four names for revenue (Sprint 10), because nothing tells users which one is official.","use":"Domain workspaces with named owners, separate Dev/Test/Prod for content many people rely on, promotion for good team content, certification with written criteria for company-wide models.","avoid":"Certifying content no one owns, or a review process so heavy that teams stop asking."},"verified":{"date":"2026-10-01","context":"Endorsement, domains and workspace roles docs (Microsoft Learn, Sept 2026)","review_after_days":120},"refs":[{"title":"Endorsement overview","url":"https://learn.microsoft.com/en-us/fabric/governance/endorsement-overview"},{"title":"Fabric domains","url":"https://learn.microsoft.com/en-us/fabric/governance/domains"},{"title":"Roles in workspaces","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/roles-workspaces"}],"asg":[{"t":"A workspace and domain plan for Northwind","time":"40 min","ds":"data/experience/s10/workspaces.csv","guidance":"B","brief":"Using the Sprint 10 inventory, propose how workspaces should be organised: names, domains, who owns them, which ones get Dev/Test/Prod, and what happens to personal and test workspaces.","req":["A naming convention.","A domain per business area with an owner.","Workspace roles: who is Admin, Member, Contributor, Viewer, and why consumers use apps instead of workspace roles.","Which workspaces need deployment pipelines."],"exp":"Domain workspaces (Sales, Finance, Operations, Marketing, HR, Supply Chain) with named owners and a convention like \"<Domain> – <Purpose> [Dev|Test]\"; at most two or three Admins per workspace; consumers through apps or audiences; pipelines for workspaces holding certified models; personal and test workspaces kept out of production use."},{"t":"Write the certification criteria","time":"30 min","ds":"—","guidance":"C","brief":"Elena asks for the criteria a semantic model must meet before it's certified, short enough that people read it, strict enough that \"certified\" means something.","req":["Ownership, documentation, testing, security, refresh, performance and change control.","Who can certify and how certification is reviewed or removed."],"exp":"One page: named business and technical owner; KPI dictionary and measure descriptions; data and model tests passing; RLS test matrix where relevant; refresh monitored with team alerts; meets the performance budget; changes through Git and a pipeline; reviewed yearly; certification removed when criteria lapse. Only a small, named group can certify."},{"t":"Promoted or certified?","time":"15 min","ds":"—","guidance":"B","brief":"Classify five items: endorse as Promoted, Certified, or neither. Justify each.","req":["The shared sales model with an owner, tests and a KPI dictionary.","Marketing's campaign model, used by its own team, maintained but undocumented.","A copy of the sales model someone made to add one measure.","Finance's board pack model, owned by the CFO's team, reconciled to the ledger monthly.","A one-off analysis for a single meeting."],"exp":"Certified: shared sales model, Finance board pack. Promoted: Marketing's model (useful, maintained, not company-wide). Neither: the copy (merge the measure into the shared model and retire it) and the one-off (personal workspace, then delete)."}],"int":[{"q":"Promoted vs certified?","a":"Promotion means the owner thinks the item is ready to share; any member with write permission can promote. Certification means it meets organisational standards, and only people the admin authorises can certify. Certified items appear first in discovery."},{"q":"What are Fabric domains for?","a":"Grouping workspaces by business area so governance (ownership, settings, discovery) can be delegated to domain admins and data is easier to find in the OneLake catalog."},{"q":"Why shouldn't report consumers be workspace Viewers on a development workspace?","a":"They'd see work in progress and unfinished content. Consumers should use apps (or audiences) from production workspaces; workspace roles are for people who build or administer."},{"q":"What makes governance actually work?","a":"Making the governed path the easiest one: certified models that are easy to find and good to use, a light process, clear owners, and data on usage to decide what to keep."}],"ass":[{"type":"mcq","q":"Who can certify a semantic model?","o":["Any workspace member","Only users authorised by the Fabric administrator for certification","Only the model owner","Anyone with Build permission"],"a":1,"why":"Certification is restricted to people the admin has authorised; promotion is open to contributors."},{"type":"mcq","q":"A team copies the certified sales model to add one measure. Best response:","o":["Certify the copy too","Add the measure to the certified model (or a composite on top) and retire the copy","Ignore it","Delete both"],"a":1,"why":"Copies drift; extend the shared model instead."},{"type":"task","q":"In a trial tenant, promote one model, request certification for another, and find both in the OneLake catalog with the endorsement filter.","hint":"Settings → Endorsement and discovery on the item."}],"module":"governance"},{"id":"gov-protect","name":"Sensitivity labels, OLS, export controls and tenant settings","ds":["DimEmployee"],"skills":["governance","security"],"stage":"architect","why":{"matters":"Data leaves Power BI through exports, Excel, emails and PDFs. Labels and settings decide whether protection travels with it.","failure":"A payroll export to Excel is emailed outside the company; nothing marked it as confidential and nothing stopped the export.","use":"Sensitivity labels on sensitive models and reports (inherited downstream and into exports), OLS for columns some users must not see, export settings per report, tenant settings restricted to security groups, least privilege everywhere.","avoid":"Turning off export for everyone: people screenshot or copy instead, and you lose the audit trail."},"verified":{"date":"2026-10-01","context":"Sensitivity labels in Power BI/Fabric, OLS, export and tenant settings docs (Microsoft Learn, Sept 2026)","review_after_days":120},"refs":[{"title":"Sensitivity labels in Power BI","url":"https://learn.microsoft.com/en-us/fabric/enterprise/powerbi/service-security-sensitivity-label-overview"},{"title":"Object-level security","url":"https://learn.microsoft.com/en-us/fabric/security/service-admin-object-level-security"},{"title":"About tenant settings","url":"https://learn.microsoft.com/en-us/fabric/admin/tenant-settings-index"}],"asg":[{"t":"Protect the payroll columns","time":"30 min","ds":"DimEmployee (course dataset)","guidance":"A","steps":["In the starter model, create a role \"Managers\" with RLS on region and a role \"Analysts\" with OLS on DimEmployee[Salary] (metadata permission None), using Tabular Editor or the TMDL view.","View as Analysts: build a table with EmployeeName and Salary. It errors; remove Salary and it works.","View as Managers: Salary visible, rows limited to the region.","Apply a sensitivity label (if your tenant has labels) and export to Excel: check the label travels with the file."],"exp":"Analysts can't see that the Salary column exists; Managers see salaries for their region only; the exported file carries the label."},{"t":"Decide the export and sharing settings","time":"30 min","ds":"—","guidance":"C","brief":"Ava (Compliance) wants all export disabled tenant-wide after the Sprint 03 incident. Sales says they need Excel every day. Propose settings that protect sensitive data without blocking everyone.","req":["Which tenant settings you change and for which security groups.","Report-level export settings for sensitive reports.","What labels and audit provide that a blanket ban doesn't."],"exp":"Keep export for most users, restricted by security groups in tenant settings; disable underlying-data export on sensitive reports; mandatory labels on sensitive models with protection that follows exports; audit logs for exports reviewed by Compliance. A blanket ban drives screenshots and copies, which nobody can audit."},{"t":"Least privilege for a new analyst","time":"15 min","ds":"—","guidance":"B","brief":"A new Finance analyst needs to build reports on the certified board pack model, but not change the model or see payroll. What access do they get?","req":["Workspace role or item permission.","Build permission and why.","Which security roles in the model they belong to."],"exp":"No role in the model's workspace; Build permission on the semantic model (to create reports on it); membership of the Finance RLS/OLS role that excludes payroll; their own workspace (or a team workspace) for their reports."}],"int":[{"q":"What does a sensitivity label do in Power BI?","a":"It classifies content (e.g. Confidential), is shown to users, is inherited by downstream items and by exports to Excel, PowerPoint and PDF, and, with protection settings, can encrypt exported files so only authorised people can open them."},{"q":"OLS vs hiding a column?","a":"Hiding only removes it from the field list; queries can still use it. OLS removes the column (or table) for a role: it doesn't exist for those users, and any visual using it fails."},{"q":"Why restrict tenant settings to security groups?","a":"So powerful features (export, publish to web, external sharing, service principal APIs) are available to the people who need them and not to everyone, and you can review membership instead of individual cases."},{"q":"What is least privilege in Power BI terms?","a":"Consumers use apps or item sharing (Viewer-equivalent), builders get Build on models rather than workspace roles, only a few Admins per workspace, and RLS/OLS restrict what each role sees."}],"ass":[{"type":"mcq","q":"A report built on a labelled \"Confidential\" model is exported to Excel. With label inheritance:","o":["The file has no label","The file carries the Confidential label","The export fails","Only the first sheet is labelled"],"a":1,"why":"Labels flow downstream and into supported exports."},{"type":"mcq","q":"An analyst should build reports on a model without seeing its workspace. Give them:","o":["Admin on the workspace","Build permission on the semantic model","Contributor on the workspace","Nothing; it isn't possible"],"a":1,"why":"Build permission allows creating content on the model without workspace access."},{"type":"task","q":"List the five tenant settings you'd review first in a new tenant, and the group each should be limited to.","hint":"Export to Excel/CSV, publish to web, external sharing, service principals calling APIs, creating workspaces."}],"module":"governance"},{"id":"gov-monitor","name":"Monitoring, lineage, usage and retirement","ds":["ApiReports","ApiViews"],"skills":["governance","service","automation"],"stage":"architect","why":{"matters":"Content accumulates. Usage and lineage tell you what to invest in, what to fix first and what to retire safely.","failure":"A \"clean-up\" deletes a model with no report views; the monthly commission paginated report that depended on it fails on payroll day.","use":"Usage metrics and activity events for what's used, lineage and impact analysis for what depends on what, capacity metrics for cost, and a retirement process with notice and a read-only period.","avoid":"Deleting based on view counts alone."},"verified":{"date":"2026-10-01","context":"Usage metrics, lineage/impact analysis, Capacity Metrics app docs (Microsoft Learn, Sept 2026)","review_after_days":120},"refs":[{"title":"Monitor usage metrics","url":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-modern-usage-metrics"},{"title":"Lineage and impact analysis","url":"https://learn.microsoft.com/en-us/fabric/governance/impact-analysis"},{"title":"Fabric Capacity Metrics app","url":"https://learn.microsoft.com/en-us/fabric/enterprise/metrics-app"}],"asg":[{"t":"Find retirement candidates, safely","time":"35 min","ds":"reports.json, activity_views.json","guidance":"B","brief":"From the mock activity events, list the reports nobody viewed in 90 days and the most-viewed one, then say what you must check before retiring any of them.","req":["Unused reports from the activity data.","The most-viewed report and its views.","The checks before retirement (lineage, subscriptions, paginated reports, Excel connections, owners)."],"exp":"7 of 18 reports had no views in 90 days; the most viewed is \"Finance Detail Overview\" with 60 views. Before retiring: impact analysis, subscriptions, dashboard tiles, Analyze in Excel connections, owner contact, then read-only for 30 days."},{"t":"What should a BI monitoring page show?","time":"30 min","ds":"—","guidance":"C","brief":"Design one page Elena can check every Monday that shows the health of the estate. Choose at most eight numbers and justify each.","req":["Refresh, usage, capacity, ownership and quality signals.","Which numbers have thresholds and who acts on them."],"exp":"For example: failed refreshes (7 days), certified-model refresh duration trend, capacity peak utilisation and throttling, views on certified vs uncertified content, items without owner, retirement candidates, data-quality test failures, open incidents. Each with an owner and a threshold."},{"t":"Run a retirement","time":"20 min","ds":"data/experience/d05","guidance":"B","brief":"Write the retirement runbook your team will use, based on the Regional Sales Weekly drill (D05).","req":["Steps with timing.","Who's notified at each step.","What makes you stop and roll back."],"exp":"Check dependencies → notify owner and recent viewers → banner and move subscriptions/tiles → read-only 30 days → archive → delete after 90 days; stop if a dependency or an objection appears; restore from archive if needed."}],"int":[{"q":"What's the difference between usage metrics and activity events?","a":"Usage metrics reports show views and viewers for content in a workspace. Activity events (admin API or audit log) record what every user did across the tenant (views, exports, shares, edits), which is what you need for tenant-wide analysis and audits."},{"q":"What does impact analysis show?","a":"Downstream items that depend on an item (reports, dashboards, other models, dataflows) across workspaces, and how many people use them, so you can notify owners before a breaking change or retirement."},{"q":"Why can a model with zero report views still be important?","a":"It may feed paginated reports, subscriptions, composite models, Analyze in Excel workbooks or other tools that usage metrics for reports don't capture."},{"q":"What does the Capacity Metrics app tell you?","a":"How much of the capacity each item and operation uses over time, interactive vs background, and when throttling happens: the evidence for optimising or resizing."}],"ass":[{"type":"mcq","q":"A model has no report views in 90 days. Before deleting it you should check:","o":["Nothing","Lineage/impact analysis, subscriptions, paginated reports and Excel connections, and ask the owner","Only its size","The tenant settings"],"a":1,"why":"Views on reports aren't the only way content is used."},{"type":"mcq","q":"Which source tells you who exported data to Excel last week across the tenant?","o":["Report usage metrics","Activity events / audit log","Refresh history","Lineage view"],"a":1,"why":"Exports are activity events."},{"type":"task","q":"Build the Monday health page from your design using the inventory and refresh data from the automation track.","hint":"Load inventory.csv and the refresh history into a small model; one card per signal with a threshold-based colour."}],"module":"governance"}]},
{"id":"fabric","kind":"track","order":6,"cls":"fab","name":"Microsoft Fabric for BI developers","tag":"Track","tagline":"OneLake, Lakehouse vs Warehouse, the SQL analytics endpoint, Direct Lake on OneLake vs on SQL, framing and fallback, Dataflow Gen2, mirroring and medallion design.","seo":"Microsoft Fabric practice for Power BI developers: OneLake, Lakehouse, Warehouse, SQL analytics endpoint, shortcuts, Direct Lake on OneLake vs Direct Lake on SQL endpoint, framing, fallback, guardrails, Dataflow Gen2, mirroring and medallion architecture. Verified against current Microsoft documentation.","intro":"Fabric changes where data preparation happens and how semantic models read data. This track focuses on the decisions a BI developer makes in Fabric, not every Fabric workload. Fabric features change fast: each topic shows when it was last checked against Microsoft's documentation, and the CI flags it when a review is due. A Fabric trial covers every hands-on step; where you can't use one, the conceptual tasks and the Sprint 09 decision still apply.","setup":"A Fabric trial (or capacity) and a workspace you own. Upload the company pack CSVs to a lakehouse. No Spark knowledge is required: everything can be done with the UI, Dataflow Gen2 and T-SQL.","stage":"engineer","topics":[{"id":"fab-onelake","name":"OneLake, Lakehouse, Warehouse and the SQL analytics endpoint","ds":["NWOrders","NWOrderLines","NWCustomers","NWProducts"],"skills":["fabric","sql","architecture"],"stage":"engineer","why":{"matters":"Choosing the right store decides who can build on it (SQL people, Spark people, analysts), how security works and which Direct Lake option you can use.","failure":"A team builds the gold layer as SQL views on a lakehouse endpoint, then discovers that Direct Lake on OneLake can't use non-materialised views and Direct Lake on SQL falls back to DirectQuery on every query.","use":"Lakehouse when data arrives as files and engineers use Spark or Dataflow Gen2; Warehouse when the team works in T-SQL and needs multi-table transactions; shortcuts to reference data without copying it.","avoid":"Copying the same table into several lakehouses \"to be safe\": use shortcuts and one owner."},"verified":{"date":"2026-10-01","context":"Fabric data store decision guide, Lakehouse and SQL analytics endpoint docs (Microsoft Learn, Sept 2026)","cert":"DP-600 (2026-10-19)","review_after_days":90},"refs":[{"title":"Decision guide: choose a data store","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/decision-guide-data-store"},{"title":"What is a lakehouse?","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/lakehouse-overview"},{"title":"SQL analytics endpoint of a lakehouse","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/lakehouse-sql-analytics-endpoint"},{"title":"OneLake shortcuts","url":"https://learn.microsoft.com/en-us/fabric/onelake/onelake-shortcuts"}],"asg":[{"t":"Land the company pack in a lakehouse","time":"40 min","ds":"company pack CSVs","guidance":"A","steps":["Create a workspace on the trial capacity and a lakehouse called nw_bronze.","Upload the seven CSVs to Files, then Load to Tables (each becomes a Delta table).","Open the SQL analytics endpoint and run the Q1 2026 by region query from the SQL track. Compare with the expected values there.","Try an UPDATE through the SQL analytics endpoint and read the error."],"exp":"Seven Delta tables; the SQL query returns the same totals as in the SQL track (total $254,751); UPDATE fails because the SQL analytics endpoint is read-only."},{"t":"Lakehouse or Warehouse for the gold layer?","time":"25 min","ds":"—","guidance":"C","brief":"Northwind's team knows T-SQL, not Spark (Sprint 09). Choose where the cleaned star schema (gold layer) lives and justify it against the constraints, including how it will be read by a Direct Lake model.","req":["Team skills, transactions, security, how the semantic model reads it.","What you'd do with SQL views in the design."],"exp":"A Fabric Warehouse for gold: T-SQL skills, multi-table transactions, materialised tables that Direct Lake (on OneLake or on SQL) reads natively. Views are fine for ad-hoc SQL users but shouldn't be the tables a Direct Lake model reads: materialise them."},{"t":"Shortcut instead of copy","time":"20 min","ds":"—","guidance":"B","brief":"Finance has its own workspace and lakehouse, and wants the cleaned customer table owned by the sales data team. Give them access without copying it.","req":["Create a OneLake shortcut in Finance's lakehouse to the source table.","Explain who owns the data, who can change it, and how permissions apply."],"exp":"A shortcut in Finance's lakehouse points to the sales team's table; data isn't duplicated; the sales team stays the owner; access requires permission on the source as well as on Finance's lakehouse."}],"int":[{"q":"What is OneLake?","a":"A single logical data lake for the whole Fabric tenant. Every lakehouse, warehouse and many other items store their tables there in Delta Parquet format, so engines (Spark, SQL, Analysis Services) can read the same data without copying it."},{"q":"Lakehouse vs Warehouse?","a":"A lakehouse stores files and Delta tables, written mainly with Spark, Dataflow Gen2 or pipelines, with a read-only SQL analytics endpoint. A warehouse is written with T-SQL and supports multi-table transactions. Both store Delta tables in OneLake; choose by team skills and workload."},{"q":"What is the SQL analytics endpoint?","a":"An automatically created, read-only T-SQL interface over a lakehouse's (or mirrored database's) Delta tables. You can query, create views and set SQL permissions, but not modify data."},{"q":"What is a shortcut?","a":"A pointer in OneLake to data stored elsewhere (another lakehouse, ADLS, S3 and others) that appears as a folder or table without copying the data."}],"ass":[{"type":"mcq","q":"Can you run UPDATE through a lakehouse's SQL analytics endpoint?","o":["Yes","No: it's read-only","Only on views","Only as an admin"],"a":1,"why":"Write with Spark, Dataflow Gen2, pipelines, or use a Warehouse for T-SQL DML."},{"type":"mcq","q":"A team only knows T-SQL and needs multi-table transactions for its gold layer. Best fit:","o":["Lakehouse with Spark notebooks","Fabric Warehouse","Excel files in OneLake","Eventhouse"],"a":1,"why":"The warehouse is T-SQL-native and transactional."},{"type":"task","q":"Use the Fabric decision guide to classify Northwind's four workloads from Sprint 09 (sales, finance, ops, web) by store.","hint":"Consider data volume, latency, skills and who writes the data."}],"module":"fabric"},{"id":"fab-directlake","name":"Direct Lake in depth: OneLake vs SQL endpoint, framing, fallback, guardrails","ds":[],"skills":["fabric","performance","modeling","security"],"stage":"senior","why":{"matters":"Direct Lake gives near-Import speed on large data without copying it at refresh, but the two Direct Lake options behave differently when something isn't supported: one falls back to slower DirectQuery, the other fails.","failure":"A Direct Lake on SQL model silently runs as DirectQuery because a table is a SQL view; performance drops and nobody knows why.","use":"Direct Lake on OneLake for new models (multi-source, no fallback, can add Import tables); Direct Lake on SQL when you need SQL-endpoint features or a supported source only it handles; well-maintained Delta tables within the capacity guardrails.","avoid":"Treating every Direct Lake model as identical, or relying on fallback in production."},"verified":{"date":"2026-10-01","context":"Direct Lake overview (Microsoft Learn, 2026-09-02); How Direct Lake works (2026-09-09)","cert":"DP-600 (2026-10-19): Configure Direct Lake; Choose between Direct Lake on OneLake and on SQL analytics endpoint","review_after_days":60},"refs":[{"title":"Direct Lake overview","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/direct-lake-overview"},{"title":"How Direct Lake works","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/direct-lake-how-it-works"},{"title":"Integrate Direct Lake security","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/direct-lake-security-integration"}],"asg":[{"t":"Compare the two Direct Lake options","time":"30 min","ds":"—","guidance":"B","brief":"Write the one-page comparison you'd give a colleague choosing between Direct Lake on OneLake and Direct Lake on SQL analytics endpoint.","req":["Sources each can combine; fallback behaviour; SQL views; SQL-endpoint security; composite models; calculated columns; what happens when guardrails are exceeded."],"exp":"OneLake: one or more Fabric sources, can add Import tables, no DirectQuery fallback (errors instead), no non-materialised views, SQL-endpoint RLS/OLS not applied; recommended for new models. SQL: one source via its SQL analytics endpoint, falls back to DirectQuery for views, SQL-endpoint RLS/OLS and exceeded guardrails (controlled by Direct Lake behavior), can't mix with DirectQuery/Dual tables in the same model. Both: Fabric capacity only."},{"t":"Prove which mode each table uses","time":"30 min","ds":"your lakehouse from the previous topic","guidance":"B","brief":"Build a Direct Lake model on the company pack and prove, table by table, whether queries are served by Direct Lake.","req":["Run EVALUATE TABLETRAITS() and read DirectLakeFallbackInfo.","Change Direct Lake behavior to DirectLakeOnly (SQL option) and observe.","Disable automatic updates, change data, and show the model still returns the old data until you reframe."],"exp":"TABLETRAITS shows None for each Delta table; a SQL view (SQL option) shows a fallback reason and fails under DirectLakeOnly; with automatic updates off, new data appears only after a refresh (framing)."},{"t":"RLS for a Direct Lake model","time":"25 min","ds":"—","guidance":"C","brief":"Northwind needs regional RLS on the Direct Lake sales model (Sprint 09 phase 2). The data engineers propose defining RLS in the SQL analytics endpoint. Decide where RLS goes and why.","req":["Consequences for each Direct Lake option.","The recommended connection identity."],"exp":"Define RLS in the semantic model. SQL-endpoint RLS isn't applied in Direct Lake on OneLake and forces DirectQuery fallback in Direct Lake on SQL. Microsoft strongly recommends a fixed-identity cloud connection for Direct Lake models with semantic-model RLS."}],"int":[{"q":"What is framing in Direct Lake?","a":"A refresh of a Direct Lake model: it reads the Delta logs and points the model at the latest table versions without copying data. Queries then see data as of the last successful framing; columns are loaded into memory on first use (transcoding)."},{"q":"When does Direct Lake on SQL fall back to DirectQuery?","a":"When a table is a non-materialised SQL view, when the SQL analytics endpoint enforces RLS, OLS or dynamic data masking, when a table exceeds the capacity guardrails, or when tables haven't been framed. The Direct Lake behavior property (Automatic, DirectLakeOnly, DirectQueryOnly) controls it."},{"q":"Why might Direct Lake on OneLake be preferred for new models?","a":"It isn't coupled to the SQL endpoint, so it can combine several Fabric sources and Import tables, has more efficient query plans, and never silently falls back; problems surface as errors you can fix."},{"q":"What are Direct Lake guardrails?","a":"Per-SKU limits on Parquet files, row groups and rows per table and on model size. Exceeding them makes Direct Lake on SQL fall back (if allowed) and Direct Lake on OneLake fail; keep Delta tables optimised (OPTIMIZE, V-Order) or size the capacity."}],"ass":[{"type":"mcq","q":"A table in a Direct Lake on OneLake model exceeds the capacity's row-group guardrail. Queries:","o":["Fall back to DirectQuery","Fail (refresh fails and the model can't be queried until fixed)","Use Import automatically","Ignore the guardrail"],"a":1,"why":"Direct Lake on OneLake doesn't fall back."},{"type":"mcq","q":"Which property controls fallback in Direct Lake on SQL?","o":["Storage mode","Direct Lake behavior (Automatic, DirectLakeOnly, DirectQueryOnly)","Query folding","Large model format"],"a":1,"why":"It's a model property, set in the model properties or via TOM/TMSL."},{"type":"task","q":"Write the runbook entry \"Direct Lake report is suddenly slow\".","hint":"Check TABLETRAITS for fallback, Delta table file and row-group counts against guardrails, capacity memory pressure, and whether framing is current."}],"module":"fabric"},{"id":"fab-pipelines","name":"Dataflow Gen2, pipelines, mirroring and medallion design","ds":["RawOrdersExport","NWOrderLines"],"skills":["fabric","power-query","deployment","warehousing"],"stage":"engineer","why":{"matters":"In Fabric, data preparation moves out of each semantic model into shared, scheduled layers. That's what makes one definition possible for many models.","failure":"Five models each clean the same export with slightly different Power Query steps, and five \"Revenue\" numbers appear (Sprint 05, again).","use":"Bronze (raw, as landed), silver (cleaned, conformed), gold (star schema for models); Dataflow Gen2 for Power Query-style transformations, pipelines to orchestrate, mirroring to replicate operational databases continuously.","avoid":"Medallion layers for their own sake on small data. Two layers are fine if they're clearly owned."},"verified":{"date":"2026-10-01","context":"Dataflow Gen2, pipelines, mirroring (SQL Server, updated 2026-07-06) and medallion docs (Microsoft Learn)","cert":"DP-600 (2026-10-19)","review_after_days":90},"refs":[{"title":"Dataflow Gen2 overview","url":"https://learn.microsoft.com/en-us/fabric/data-factory/dataflows-gen2-overview"},{"title":"Mirroring SQL Server in Fabric","url":"https://learn.microsoft.com/en-us/fabric/mirroring/sql-server"},{"title":"Medallion lakehouse architecture","url":"https://learn.microsoft.com/en-us/fabric/onelake/onelake-medallion-lakehouse-architecture"}],"asg":[{"t":"Move the clean-up out of the model","time":"40 min","ds":"RawOrdersExport (course dataset)","guidance":"B","brief":"Turn the Beginner RawOrdersExport clean-up into a Dataflow Gen2 that writes a silver table, so every model reads the same cleaned data.","req":["Same rules as Beginner (header and total rows, dates, prices, duplicates).","Output destination: a lakehouse or warehouse table, with an explicit schema.","Refresh on a schedule; show two models reading the same table."],"exp":"A silver table with 27 rows and 8 columns, refreshed by the dataflow; both models read it, so a fix in the dataflow fixes both."},{"t":"Design the medallion layers for Northwind","time":"30 min","ds":"—","guidance":"C","brief":"Following ADR-009 (Sprint 09), design bronze, silver and gold for the sales data: what lands where, which tool writes each layer, who owns it, and which data-quality checks run between layers.","req":["Mirroring or pipelines for the operational database.","Where deduplication, currency conversion and the test-customer rule live.","The gold tables the semantic model reads."],"exp":"Bronze: mirrored NorthwindDW and landed files (owner: data engineering). Silver: deduplicated, typed, conformed tables with DQ tests (dedup, test customer, FX). Gold: star schema materialised in a Warehouse (FactSales, FactReturns, dimensions), read by a Direct Lake on OneLake model. Tests block promotion from silver to gold."},{"t":"Orchestrate: load, test, frame, notify","time":"30 min","ds":"—","guidance":"B","brief":"Build (or design) a pipeline that runs the nightly sequence so the semantic model only shows data that passed its tests.","req":["Steps: refresh the dataflow or wait for mirroring, run data-quality checks, load gold, refresh (frame) the semantic model, run model tests, notify.","What happens when a step fails."],"exp":"A pipeline: Dataflow → stored procedure DQ checks (fail stops the run) → gold load → semantic model refresh activity → test query → notify team channel; failures stop downstream steps and alert, so users keep seeing the last good data."}],"int":[{"q":"Dataflow Gen2 vs Power Query in the model?","a":"Both use Power Query. Dataflow Gen2 runs once and writes to a destination (lakehouse, warehouse and others) that many models and tools can read; Power Query in the model only serves that model. Use dataflows for shared preparation."},{"q":"What does mirroring do?","a":"Continuously replicates a supported database (for example SQL Server 2016 and later, through a gateway for on-premises) into OneLake as Delta tables with a SQL analytics endpoint, without building ETL. Replication compute is free; querying uses capacity."},{"q":"Explain the medallion architecture.","a":"Bronze holds raw data as landed, silver holds cleaned and conformed data, gold holds business-ready models (often star schemas). Each layer has an owner and tests between layers, so problems are caught before reports."},{"q":"Why orchestrate refresh in a pipeline rather than schedule each item?","a":"Dependencies: the model should refresh only after its data is loaded and tested. A pipeline encodes the order, stops on failure and notifies, so users never see half-loaded data."}],"ass":[{"type":"mcq","q":"Five models clean the same export differently. Best fix in Fabric:","o":["Copy the best query into all five","One Dataflow Gen2 writing a shared table that all five read","DirectQuery to the CSV","Calculated columns"],"a":1,"why":"One shared preparation step, one definition."},{"type":"mcq","q":"Mirroring an on-premises SQL Server into Fabric requires:","o":["Nothing","A supported SQL Server version and a data gateway (on-premises or VNet) for connectivity","A Spark notebook","Premium per user"],"a":1,"why":"On-premises sources are reached through a gateway; SQL Server 2016–2022 uses CDC, 2025 uses the change feed with Azure Arc."},{"type":"task","q":"Draw the Northwind data flow from source to report on one page, marking owners and test points.","hint":"NorthwindDW → mirror (bronze) → silver tables → gold warehouse → Direct Lake model → reports; tests at silver→gold and after model refresh."}],"module":"fabric"}]},
{"id":"modern","kind":"track","order":7,"cls":"mod","name":"Modern Power BI features","tag":"Track","tagline":"Visual calculations, Copilot workflows and their limits, paginated reports, mobile and accessible design, personalization, and AI-assisted analysis.","seo":"Modern Power BI practice for PL-300: visual calculations, Copilot in Power BI, paginated reports, mobile layouts, accessibility, personalization, automatic page refresh, forecasting, anomaly detection, clustering and AI visuals.","intro":"Product features layered on top of the fundamentals, most of them new to the PL-300 outline in April 2026. They don't replace a good model or correct DAX: Copilot answers better on a well-prepared model, and visual calculations are easier precisely because the model underneath is right. Each topic says when it was last checked against Microsoft's documentation, because these features change monthly.","setup":"Power BI Desktop (current monthly release) and the starter project. Copilot needs a paid Fabric capacity (F2 or higher) or Power BI Premium (P1 or higher): trial capacities and Pro/PPU licences alone aren't enough. Where you don't have it, the tasks describe what to evaluate.","stage":"analyst","topics":[{"id":"mod-viscalc","name":"Visual calculations","ds":["FactSales","DimProduct","DimDate"],"skills":["dax","visuals"],"stage":"analyst","why":{"matters":"Running totals, moving averages, percent of parent and versus-previous are the most common report calculations. Visual calculations express them in one line on the visual, without filter-context gymnastics.","failure":"A model collects dozens of one-off measures (\"Running Sales for Chart 3\") that nobody else uses and nobody dares delete.","use":"Calculations that only make sense for one visual's layout: running sums along its axis, percent of the visual's parent, comparisons with the previous row.","avoid":"Business definitions that other reports need (put those in model measures), or anything you need to filter, sort or export: visual calculations can't be filtered, sorted, reused across visuals or exported."},"verified":{"date":"2026-10-01","context":"Visual calculations overview (Microsoft Learn, 2026-08-31)","cert":"PL-300 (2026-04-20): Create visual calculations by using DAX","review_after_days":90},"refs":[{"title":"Visual calculations overview","url":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-visual-calculations-overview"},{"title":"Create visual calculations","url":"https://learn.microsoft.com/en-us/power-bi/transform-model/desktop-visual-calculations-create"}],"asg":[{"t":"Four visual calculations in ten minutes","time":"25 min","ds":"FactSales, DimProduct, Dates","guidance":"A","steps":["Build a matrix with Dates[MonthName] on rows and [Net Sales] as the value (Beginner model).","Select the visual → New calculation. Add Running = RUNNINGSUM([Net Sales]).","Add vs Previous = [Net Sales] - PREVIOUS([Net Sales]) and Moving avg = MOVINGAVERAGE([Net Sales], 2).","Add Category to rows above MonthName and add Pct of parent = DIVIDE([Net Sales], COLLAPSE([Net Sales], ROWS)).","Try RUNNINGSUM([Net Sales], HIGHESTPARENT) and explain how it differs from the first running sum."],"exp":"The running sum on the March row equals the visual's total; vs Previous is blank on the first row; percent of parent sums to 100% within each category; with Reset = HIGHESTPARENT the running sum restarts for each category."},{"t":"Measure or visual calculation?","time":"20 min","ds":"—","guidance":"C","brief":"The executive page has six calculations. Decide for each whether it should be a model measure or a visual calculation, considering reuse, filtering, export and performance.","req":["Net Sales YoY % (used on four pages).","Running total on one line chart.","Percent of category total in one matrix.","Rank of customers used in a slicer.","Margin % in the KPI dictionary.","Difference from the first month in one table."],"exp":"Measures: YoY %, customer rank (needs filtering/slicing), Margin % (shared definition). Visual calculations: the running total, percent of category in that matrix, difference from the first month (FIRST)."},{"t":"Find the limits","time":"20 min","ds":"your matrix","guidance":"B","brief":"Before recommending visual calculations to the team, test what they can't do.","req":["Try to filter or sort by a visual calculation.","Export the visual's data.","Copy the visual calculation to another visual.","Use RELATED inside one."],"exp":"No filtering or sorting by the calculation, results aren't included in data exports, it can't be reused on other visuals, and RELATED, RELATEDTABLE and USERELATIONSHIP aren't available."}],"int":[{"q":"What is a visual calculation?","a":"A DAX calculation defined on a visual and evaluated over the visual's own data (the visual matrix), not stored in the model. It can refer only to fields on the visual and is usually simpler and often faster for layout-dependent calculations like running sums."},{"q":"What do the Axis and Reset parameters do?","a":"Axis chooses which direction the calculation traverses the visual matrix (ROWS, COLUMNS, …). Reset decides when it restarts: NONE, HIGHESTPARENT (absolute), LOWESTPARENT (relative), or a level number or column."},{"q":"Name some functions specific to visual calculations.","a":"RUNNINGSUM, MOVINGAVERAGE, PREVIOUS, NEXT, FIRST, LAST, COLLAPSE, COLLAPSEALL, EXPAND, EXPANDALL, RANGE, LOOKUP, LOOKUPWITHTOTALS, ISATLEVEL."},{"q":"When should you not use a visual calculation?","a":"For business definitions others need (they can't be reused), when you need to filter or sort by it, when it must appear in exports, or when it needs relationships (RELATED, USERELATIONSHIP)."}],"ass":[{"type":"mcq","q":"Which expression gives each row's share of its parent in a visual calculation?","o":["DIVIDE([Sales], CALCULATE([Sales], ALL(Product)))","DIVIDE([Sales], COLLAPSE([Sales], ROWS))","RUNNINGSUM([Sales])","RELATED([Sales])"],"a":1,"why":"COLLAPSE evaluates at the parent level of the axis."},{"type":"mcq","q":"A visual calculation's results in an Export data file:","o":["Are included","Are excluded","Replace the measures","Cause the export to fail"],"a":1,"why":"Exports exclude visual calculation results; hidden fields appear only in underlying-data exports."},{"type":"task","q":"Rebuild one running-total measure from the Intermediate DAX topic as a visual calculation, and compare the DAX length and Performance Analyzer timing.","hint":"RUNNINGSUM([Net Sales]) vs a CALCULATE with a date filter; visual calculations operate on aggregated data, often faster."}],"module":"modern"},{"id":"mod-copilot","name":"Copilot-assisted workflows and their limits","ds":[],"skills":["visuals","dax","governance","communication"],"stage":"developer","why":{"matters":"Copilot can draft report pages, summarise a model, write DAX queries and suggest measure descriptions. Its answers are only as good as the model it reads, and someone still has to check them.","failure":"A manager asks Copilot \"what was revenue last quarter?\" and gets a confident number from the wrong one of three revenue measures, because the model had no descriptions and three similar names (Sprint 05).","use":"Drafting pages and narratives, exploring an unfamiliar model, first drafts of DAX queries and descriptions, summaries for subscriptions. Prepare the model for AI: clear names, descriptions, synonyms, hidden helper fields.","avoid":"Treating an answer as verified, using it on unprepared models for decisions, or assuming it's available everywhere: it needs paid capacity, an enabled tenant setting and a supported region."},"verified":{"date":"2026-10-01","context":"Copilot for Power BI overview (Microsoft Learn, 2026-08-24): F2+/P1+ capacity, trial not supported; report pane GA, standalone and app experiences in preview","cert":"PL-300 (2026-04-20): Copilot narrative visual, report pages, model summary","review_after_days":60},"refs":[{"title":"Copilot for Power BI overview","url":"https://learn.microsoft.com/en-us/power-bi/create-reports/copilot-introduction"},{"title":"Prepare your data for AI","url":"https://learn.microsoft.com/en-us/power-bi/create-reports/copilot-prepare-data-ai"},{"title":"Privacy, security and responsible use of Copilot in Power BI","url":"https://learn.microsoft.com/en-us/fabric/get-started/copilot-power-bi-privacy-security"}],"asg":[{"t":"Prepare the model so AI answers correctly","time":"40 min","ds":"your certified model from Sprint 05 (or the starter)","guidance":"B","brief":"Before Copilot is switched on for the sales app, make the model unambiguous for a machine reader.","req":["Descriptions on every visible measure (from the KPI dictionary).","Clear names; hide keys and helper columns.","Synonyms for common business words (revenue, turnover, sales).","Decide which measure a question about \"revenue\" should land on."],"exp":"Every visible measure described, helper fields hidden, synonyms added, and \"revenue\" mapped to Net Revenue (ledger) in descriptions and synonyms, so a natural-language question has one obvious target."},{"t":"Check Copilot's work","time":"30 min","ds":"a model on F2+ or P1+ capacity","guidance":"C","brief":"Ask Copilot five questions you already know the answers to (use Sprint 01/02 numbers), and have it draft a report page and a DAX query. Grade each output as correct, partly correct or wrong, and explain why.","req":["Five questions with known answers.","One drafted page and one DAX query reviewed line by line.","What you'd tell users about trusting answers."],"exp":"A graded table. Typical findings: right when the question maps to one well-described measure, wrong or ambiguous when names are similar or the time period is implicit; drafted DAX needs review for filters and totals. Users should verify answers against the certified report before acting."},{"t":"Should we turn it on?","time":"20 min","ds":"—","guidance":"D","brief":"Elena asks whether to enable Copilot for all report users now, for a pilot group, or not yet. Recommend one, considering capacity cost, data preparation, privacy and training.","req":["Prerequisites (capacity, tenant setting, region).","Where Copilot compute is billed.","Which models are ready.","How you'd measure the pilot."],"exp":"A pilot: enable for a security group on certified, prepared models only; monitor Copilot CU in the Capacity Metrics app; publish guidance on verifying answers; expand when answer quality and cost are acceptable."}],"int":[{"q":"What does Copilot need to work in Power BI?","a":"A paid Fabric capacity (F2 or higher) or Premium (P1 or higher), the tenant setting allowing Copilot (Azure OpenAI features) enabled, and a supported region. Pro or PPU licences alone and trial capacities aren't enough."},{"q":"How do you make a model better for Copilot?","a":"Prepare it for AI: clear, business names; descriptions on measures and tables; synonyms; hide technical fields; one obvious measure per business concept; verified answers or instructions where supported."},{"q":"Is Copilot output trustworthy?","a":"It's a draft. Answers grounded in the semantic model can still pick the wrong measure or period, and questions outside the data are answered from general knowledge. Verify against certified content before decisions, and say so in user guidance."},{"q":"How is Copilot usage charged?","a":"It consumes capacity units on the Fabric capacity (or a dedicated Fabric Copilot capacity), processed as background operations; the Capacity Metrics app shows Copilot usage."}],"ass":[{"type":"mcq","q":"A user has a Power BI Pro licence and the report is in a workspace on a Pro (shared) capacity. Copilot:","o":["Works","Isn't available: it needs F2+/P1+ capacity","Works in Desktop only","Works on trial capacity"],"a":1,"why":"Copilot requires paid organizational capacity."},{"type":"mcq","q":"The most effective way to improve Copilot answers about \"revenue\" is:","o":["Longer prompts","Clear measure names, descriptions and synonyms in the model","More visuals","Turning off RLS"],"a":1,"why":"Copilot grounds answers in the model's metadata."},{"type":"task","q":"Write a half-page user guide: what Copilot is good for in our reports, how to check an answer, and who to ask when it's wrong.","hint":"Point users to the certified report and the KPI dictionary as the reference."}],"module":"modern"},{"id":"mod-report","name":"Paginated reports, mobile layouts, accessibility and personalization","ds":["FactSales","DimCustomer","DimProduct"],"skills":["visuals","communication","service"],"stage":"analyst","why":{"matters":"A report that can't be read on a phone, by a screen-reader user, or printed as a 40-page invoice list fails part of its audience, often the part that matters most.","failure":"The regional sales report is used on phones in the field, but its mobile layout was never built; managers pinch and zoom, then ask for a PDF every Monday.","use":"Paginated reports for pixel-perfect, printable, many-page output; mobile layouts for field users; accessibility settings (alt text, tab order, contrast, titles) for everyone; personalization so users adjust visuals without copies.","avoid":"Colour as the only signal, interactive reports pretending to be printouts, and paginated reports for exploration."},"verified":{"date":"2026-10-01","context":"Paginated reports, mobile layout, accessibility and personalization docs (Microsoft Learn, Sept 2026)","cert":"PL-300 (2026-04-20): paginated reports, mobile, personalization, accessibility","review_after_days":120},"refs":[{"title":"When to use paginated reports","url":"https://learn.microsoft.com/en-us/power-bi/guidance/report-paginated-or-power-bi"},{"title":"Optimize reports for mobile","url":"https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-create-mobile-optimized-report-about"},{"title":"Design accessible reports","url":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-accessibility-creating-reports"},{"title":"Let users personalize visuals","url":"https://learn.microsoft.com/en-us/power-bi/create-reports/power-bi-personalize-visuals"}],"asg":[{"t":"Make the executive page accessible","time":"40 min","ds":"your Beginner executive page","guidance":"B","brief":"Run the Beginner executive page through an accessibility review and fix what you find.","req":["Alt text on every visual (what it shows, not \"bar chart\").","Tab order and titles; no information conveyed by colour alone; contrast checked.","Test with keyboard only and with a screen reader (Narrator or NVDA)."],"exp":"Every visual has meaningful alt text (ideally dynamic, from a measure), tab order follows the reading order, status uses icons or text as well as colour, and the page can be used with the keyboard alone."},{"t":"A mobile layout for field managers","time":"30 min","ds":"your Beginner report","guidance":"B","brief":"Regional managers check sales on their phones between store visits. Build the mobile layout for the page they use.","req":["Only the visuals that answer their question, in priority order.","Slicers usable with a thumb.","Test in the Power BI mobile app or the phone emulator."],"exp":"A portrait mobile layout with three to five visuals (headline numbers first), slicers at the top, no horizontal scrolling, tested in the mobile app."},{"t":"Paginated or interactive?","time":"20 min","ds":"—","guidance":"C","brief":"Decide the right report type for four requests and justify each.","req":["Monthly customer statements, one PDF per customer.","An exploratory dashboard of sales by region.","A 40-page price list printed for stores.","Commission statements emailed to each rep on the 1st (Sprint D05)."],"exp":"Paginated: statements, the price list and commission statements (fixed layout, many pages, per-recipient output, subscriptions). Interactive Power BI report: the exploratory dashboard."}],"int":[{"q":"When do you choose a paginated report?","a":"When the output must be printed or exported with a fixed layout, spans many pages, lists detail rows (invoices, statements), or is generated per recipient. Interactive reports are for exploration and summaries."},{"q":"What makes a Power BI report accessible?","a":"Alt text on visuals, a logical tab order, titles and labels, sufficient contrast, not relying on colour alone, readable font sizes, and testing with keyboard navigation and a screen reader."},{"q":"What is report personalization?","a":"A setting that lets viewers change a visual's type, fields or aggregation for themselves and save it as a personal bookmark, without editing the report or making a copy."},{"q":"Why build a mobile layout instead of relying on the phone showing the desktop page?","a":"The desktop page shrinks to unreadable size. A mobile layout reorders and sizes visuals for portrait use, so the most important numbers appear first and controls are usable by touch."}],"ass":[{"type":"mcq","q":"Statements must be emailed as one PDF per customer each month. Best fit:","o":["Interactive report with bookmarks","Paginated report with a data-driven subscription or parameters","Dashboard","Excel export"],"a":1,"why":"Fixed layout, per-recipient output."},{"type":"mcq","q":"A KPI turns red when below target, with no other cue. Accessibility problem?","o":["No","Yes: colour alone conveys the status","Only on mobile","Only when printed"],"a":1,"why":"Add an icon, label or text so colour-blind and screen-reader users get the information."},{"type":"task","q":"Enable personalization on one report page and test it as a viewer.","hint":"Report settings → Personalize visuals; viewers see the personalize icon on each visual."}],"module":"modern"},{"id":"mod-ai","name":"Analytics features: forecasting, anomalies, clustering, AI visuals and auto page refresh","ds":["FactSales","WebEvents","DimCustomer"],"skills":["visuals","communication","performance"],"stage":"developer","why":{"matters":"Built-in analytics answer \"what's unusual, what's next, what groups exist\" without a data scientist, and they're part of PL-300. They also produce confident-looking results from too little data.","failure":"A forecast shaded band on three months of data goes into a board deck as a prediction.","use":"Forecasting and anomaly detection on line charts with enough history; clustering and grouping for segmentation; Key influencers and Decomposition tree for exploration; automatic page refresh for operational pages on DirectQuery or Direct Lake.","avoid":"Presenting AI visual output as fact without checking sample size and assumptions; automatic page refresh on Import models or at intervals faster than the data changes."},"verified":{"date":"2026-10-01","context":"Analytics pane, anomaly detection, AI visuals and automatic page refresh docs (Microsoft Learn, Sept 2026)","cert":"PL-300 (2026-04-20): Identify patterns and trends; Configure automatic page refresh","review_after_days":120},"refs":[{"title":"Anomaly detection","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-anomaly-detection"},{"title":"Key influencers visual","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualization-influencers"},{"title":"Automatic page refresh","url":"https://learn.microsoft.com/en-us/power-bi/create-reports/desktop-automatic-page-refresh"}],"asg":[{"t":"Forecast and find anomalies, then doubt them","time":"30 min","ds":"FactSales, Dates","guidance":"B","brief":"Add a forecast and anomaly detection to a daily Net Sales line chart of the course data, then decide whether either result is fit to show an executive.","req":["Analytics pane → Forecast; Find anomalies on the line.","Explain what the sensitivity and confidence settings do.","Judge whether 90 days of data is enough, and what you'd say on the slide."],"exp":"Both features run, but on about three months of daily data with returns and gaps the forecast band is wide and anomalies are mostly normal weekly variation. Not fit for an executive slide without much more history; say \"exploratory\" if shown at all."},{"t":"Segment customers with clustering","time":"30 min","ds":"FactSales, DimCustomer","guidance":"B","brief":"Create customer segments from Net Sales and Orders with automatic clustering on a scatter chart, and compare them with a rule-based segmentation you can explain.","req":["Scatter chart by customer; ... → Automatically find clusters.","A rule-based grouping (e.g. ABC classes from Advanced).","Which would you give to Sales, and why?"],"exp":"Clusters appear as a new field; they're harder to explain and can change on refresh. A rule-based segmentation (ABC by cumulative share) is stable and explainable, so it's better for Sales; clusters are good for exploration."},{"t":"Real-time page, or not?","time":"20 min","ds":"—","guidance":"C","brief":"Operations asks for a warehouse page refreshing every 5 seconds. Decide whether and how to use automatic page refresh, considering storage mode, capacity limits and how often the data actually changes.","req":["Which storage modes support it.","Fixed interval vs change detection.","Admin limits and capacity cost.","What interval the decision really needs."],"exp":"Automatic page refresh works with DirectQuery (and Direct Lake) sources, not Import; admins set minimum intervals and can disable it; change detection refreshes only when a measure changes. Agree an interval with Ops based on how quickly they act (minutes, not seconds), and check capacity load."}],"int":[{"q":"What does anomaly detection in Power BI do?","a":"On a line chart with a date axis, it flags points outside an expected range learned from the series, with adjustable sensitivity, and can explain anomalies by other fields. It needs enough history to be meaningful."},{"q":"Key influencers vs Decomposition tree?","a":"Key influencers ranks the factors associated with a metric's value or a category (statistically). Decomposition tree lets users drill into a measure across dimensions, optionally with AI splits picking the highest or lowest next level."},{"q":"When is automatic page refresh appropriate?","a":"For operational pages on DirectQuery or Direct Lake data that changes frequently and drives quick action. Use change detection where possible, the longest interval the decision allows, and respect the capacity admin's minimum interval."},{"q":"What's the risk of AI visuals in reports?","a":"They look authoritative. With small samples, correlated fields or changing data, their findings may be noise. Check sample sizes, explain what they show, and don't present associations as causes."}],"ass":[{"type":"mcq","q":"Automatic page refresh works with:","o":["Import only","DirectQuery (and Direct Lake) sources","Excel files","Paginated reports only"],"a":1,"why":"Import data only changes at refresh, so page refresh wouldn't show new data."},{"type":"mcq","q":"Key influencers finds that customers on Mobile buy less. This shows:","o":["Mobile causes lower spend","An association worth investigating, not a cause","A data error","Nothing"],"a":1,"why":"AI visuals show statistical associations."},{"type":"task","q":"Add a Decomposition tree on Net Sales by Region → Category → Product and use AI split once. Explain the result to a non-analyst in two sentences.","hint":"AI split picks the dimension with the highest (or lowest) value at the next level."}],"module":"modern"}]}
];
